begin;

update public.notification_messages
set is_active = false
where language_code in ('en', 'el', 'sr', 'bg', 'mk', 'uk', 'ka', 'ru', 'sq')
  and country_code is null
  and calendar_code is null;

insert into public.notification_messages (
  language_code,
  country_code,
  calendar_code,
  day_type,
  theme,
  title_template,
  body_template,
  is_active
) values
  ('bg', null, null, 'black_cross', 'black_cross_001', 'Молитва със смирение', 'Днес е празник с черен кръст: {feast_title}. Издигни днес молитва със смирено сърце. Бог приема тези, които Го търсят с вяра.', true),
  ('bg', null, null, 'black_cross', 'black_cross_002', 'Помни вечността', 'Днес е празник с черен кръст: {feast_title}. Мисълта за вечния живот ни подтиква да живеем с повече любов, търпение и вяра.', true),
  ('bg', null, null, 'black_cross', 'black_cross_003', 'Почит чрез молитва', 'Днес е празник с черен кръст: {feast_title}. Почитай този ден чрез молитва и доброта. Чистото сърце е най-красивото свидетелство.', true),
  ('bg', null, null, 'black_cross', 'black_cross_004', 'Запази мира', 'Днес е празник с черен кръст: {feast_title}. Спокойствието на душата се запазва чрез молитва и доверие в Бога. Не позволявай тревогите да смущават сърцето ти.', true),
  ('bg', null, null, 'black_cross', 'black_cross_005', 'Бъди постоянен', 'Днес е празник с черен кръст: {feast_title}. Вярата се укрепва чрез търпение и молитва. Остани близо до Бога всеки ден.', true),
  ('bg', null, null, 'black_cross', 'black_cross_006', 'Момент на размисъл', 'Днес е празник с черен кръст: {feast_title}. Спри за няколко минути и издигни молитва. Тишината приближава душата до Бога.', true),
  ('bg', null, null, 'black_cross', 'black_cross_007', 'Любов и доброта', 'Днес е празник с черен кръст: {feast_title}. Проявявай любов и доброта към околните. Добри дела са плод на вярващо сърце.', true),
  ('bg', null, null, 'black_cross', 'black_cross_008', 'Чиста мисъл', 'Днес е празник с черен кръст: {feast_title}. Дръж ума и сърцето си насочени към Бога. Той е опората на тези, които Го търсят.', true),
  ('bg', null, null, 'black_cross', 'black_cross_009', 'Спомен с молитва', 'Днес е празник с черен кръст: {feast_title}. Молитвата, произнесена със смирение, носи мир на душата и укрепва надеждата в Бога.', true),
  ('bg', null, null, 'black_cross', 'black_cross_010', 'Живей с вяра', 'Днес е празник с черен кръст: {feast_title}. Всеки ден е призив за приближаване към Бога. Върви напред с доверие и мир.', true),
  ('bg', null, null, 'black_cross', 'black_cross_011', 'Душа в мир', 'Днес е празник с черен кръст: {feast_title}. Не позволявай бързането да отнеме спокойствието ти. Молитвата и смирението носят покой на сърцето.', true),
  ('bg', null, null, 'black_cross', 'black_cross_012', 'Безмерна доброта', 'Днес е празник с черен кръст: {feast_title}. Жест, направен с любов, може да донесе утешение на ближния. Не се уморявай да правиш добро.', true),
  ('bg', null, null, 'black_cross', 'black_cross_013', 'Непоклатима надежда', 'Днес е празник с черен кръст: {feast_title}. Във всяка ситуация, поставяй доверието си в Бога. Той укрепва вярващата душа.', true),
  ('bg', null, null, 'black_cross', 'black_cross_014', 'Пътят на смирението', 'Днес е празник с черен кръст: {feast_title}. Смирението и търпението носят мир на сърцето. Търси доброто във всяка стъпка, която правиш.', true),
  ('bg', null, null, 'black_cross', 'black_cross_015', 'Близо до Бога', 'Днес е празник с черен кръст: {feast_title}. Започни този ден с молитва и запази сърцето си отворено за Божията воля.', true),
  ('bg', null, null, 'black_cross', 'black_cross_016', 'Молитва от сърце', 'Днес е празник с черен кръст: {feast_title}. Издигни молитва със смирение и доверие. Бог вижда сърцето, което Го търси искрено.', true),
  ('bg', null, null, 'black_cross', 'black_cross_017', 'Търси спокойствието', 'Днес е празник с черен кръст: {feast_title}. Спокойствието на душата се постига чрез молитва, търпение и приближаване до Бога.', true),
  ('bg', null, null, 'black_cross', 'black_cross_018', 'Бъди милостив', 'Днес е празник с черен кръст: {feast_title}. Проявявай разбиране и доброта към ближния. Милостинята е плод на вярващо сърце.', true),
  ('bg', null, null, 'black_cross', 'black_cross_019', 'Полезен ден', 'Днес е празник с черен кръст: {feast_title}. Изпълнявай задълженията си с вяра и смирение. Всяко добро дело е свидетелство за любовта.', true),
  ('bg', null, null, 'black_cross', 'black_cross_020', 'Мисъл към Бога', 'Днес е празник с черен кръст: {feast_title}. Насочи мислите си към Бога и запази мира в душата си през целия ден.', true),
  ('bg', null, null, 'black_cross', 'black_cross_021', 'Запази вярата', 'Днес е празник с черен кръст: {feast_title}. Дори в изпитания, не губи доверието си в Бога. Той укрепва душата, която се моли.', true),
  ('bg', null, null, 'black_cross', 'black_cross_022', 'Говори с нежност', 'Днес е празник с черен кръст: {feast_title}. Думите, произнесени с любов и търпение, носят мир и укрепват околните.', true),
  ('bg', null, null, 'black_cross', 'black_cross_023', 'Смирено сърце', 'Днес е празник с черен кръст: {feast_title}. Смирението отваря душата към Божията работа и носи мир всеки ден.', true),
  ('bg', null, null, 'black_cross', 'black_cross_024', 'Спомен с уважение', 'Днес е празник с черен кръст: {feast_title}. Запази в сърцето си уважение и молитва. Бог познава чистите желания на душата.', true),
  ('bg', null, null, 'black_cross', 'black_cross_025', 'Остани постоянен', 'Днес е празник с черен кръст: {feast_title}. Не спирай да търсиш доброто. Вярата и търпението дават сила на душата.', true),
  ('bg', null, null, 'black_cross', 'black_cross_026', 'Доброта приближава', 'Днес е празник с черен кръст: {feast_title}. Прост жест, направен с любов, може да донесе утешение и мир на ближния.', true),
  ('bg', null, null, 'black_cross', 'black_cross_027', 'Молитва и мир', 'Днес е празник с черен кръст: {feast_title}. Нека молитвата ръководи деня ти. Бог дава мир на тези, които Го търсят.', true),
  ('bg', null, null, 'black_cross', 'black_cross_028', 'Пътят на вярата', 'Днес е празник с черен кръст: {feast_title}. Върви напред с доверие и смирение. Бог е опората на тези, които остават постоянни.', true),
  ('bg', null, null, 'black_cross', 'black_cross_029', 'Благодарно сърце', 'Днес е празник с черен кръст: {feast_title}. Благодари на Бога за благословиите, които получаваш, и запази сърцето си изпълнено с надежда.', true),
  ('bg', null, null, 'black_cross', 'black_cross_030', 'Мир и доброта', 'Днес е празник с черен кръст: {feast_title}. Живей този ден с нежност, молитва и любов. Така се укрепва вярващата душа.', true),
  ('bg', null, null, 'black_cross', 'black_cross_031', 'Остани в молитва', 'Днес е празник с черен кръст: {feast_title}. Започни този ден с молитва на смирение. Бог укрепва душата, която Го търси с вяра.', true),
  ('bg', null, null, 'black_cross', 'black_cross_032', 'Спокойствие за сърцето', 'Днес е празник с черен кръст: {feast_title}. Запази мира в душата си и не позволявай смущението да завладее мислите ти. Молитвата носи покой.', true),
  ('bg', null, null, 'black_cross', 'black_cross_033', 'Действаща любов', 'Днес е празник с черен кръст: {feast_title}. Проявявай любов чрез дела и добри думи. Доброто сближава сърцата и укрепва вярата.', true),
  ('bg', null, null, 'black_cross', 'black_cross_034', 'Мисъл на благодарност', 'Днес е празник с черен кръст: {feast_title}. Благодари на Бога за Неговата грижа и запази надеждата във всяка ситуация.', true),
  ('bg', null, null, 'black_cross', 'black_cross_035', 'Нежност и мир', 'Днес е празник с черен кръст: {feast_title}. Нежността е знак на сърце, което се доверява на Бога. Запази я във всички свои срещи.', true),
  ('bg', null, null, 'black_cross', 'black_cross_036', 'Дело с любов', 'Днес е празник с черен кръст: {feast_title}. Не минавай безразлично покрай нуждаещия се. Любовта се проявява чрез прости и искрени дела.', true),
  ('bg', null, null, 'black_cross', 'black_cross_037', 'Постоянна вяра', 'Днес е празник с черен кръст: {feast_title}. Остани непоклатим вярата и молитвата. Бог укрепва търпеливата душа.', true),
  ('bg', null, null, 'black_cross', 'black_cross_038', 'Търси смирението', 'Днес е празник с черен кръст: {feast_title}. Смирението носи мир на сърцето и отваря пътя към приближаването до Бога.', true),
  ('bg', null, null, 'black_cross', 'black_cross_039', 'Молитва и търпение', 'Днес е празник с черен кръст: {feast_title}. Там, където са молитвата и търпението, душата намира силата да продължи напред.', true),
  ('bg', null, null, 'black_cross', 'black_cross_040', 'Мир в семейството', 'Днес е празник с черен кръст: {feast_title}. Бъди източник на мир и доброта в дома си. Любовта се запазва чрез търпение и разбиране.', true),
  ('bg', null, null, 'black_cross', 'black_cross_041', 'Гледай към доброто', 'Днес е празник с черен кръст: {feast_title}. Избирай доброто във всяко решение и запази сърцето си близо до Бога.', true),
  ('bg', null, null, 'black_cross', 'black_cross_042', 'Спокойно сърце', 'Днес е празник с черен кръст: {feast_title}. Прощавай искрено и остави мира да ръководи душата ти всеки ден.', true),
  ('bg', null, null, 'black_cross', 'black_cross_043', 'Доброта без шум', 'Днес е празник с черен кръст: {feast_title}. Добри дела не се нуждаят от похвала. Бог вижда любовта, проявена в тайна.', true),
  ('bg', null, null, 'black_cross', 'black_cross_044', 'Пътят на мира', 'Днес е празник с черен кръст: {feast_title}. Върви по пътя на мира, с търпение и вяра. Бог е близо до смирените.', true),
  ('bg', null, null, 'black_cross', 'black_cross_045', 'Доверие и молитва', 'Днес е празник с черен кръст: {feast_title}. Поверявай този ден на Бога и запази сърцето си спокойно чрез молитва.', true),
  ('bg', null, null, 'black_cross', 'black_cross_046', 'Ден с молитва', 'Днес е празник с черен кръст: {feast_title}. Започни този ден с молитва и запази сърцето си близо до Бога. Той дава мир на вярващата душа.', true),
  ('bg', null, null, 'black_cross', 'black_cross_047', 'Търпение и вяра', 'Днес е празник с черен кръст: {feast_title}. Не се отчайвай пред изпитанията. Търпението и вярата укрепват душата всеки ден.', true),
  ('bg', null, null, 'black_cross', 'black_cross_048', 'Чисти мисли', 'Днес е празник с черен кръст: {feast_title}. Запази ума и сърцето си насочени към доброто. Молитвата осветява пътя на вярващия.', true),
  ('bg', null, null, 'black_cross', 'black_cross_049', 'Близо до ближния', 'Днес е празник с черен кръст: {feast_title}. Едно добро дело и нежно слово могат да донесат утешение. Дари ги с любов и смирение.', true),
  ('bg', null, null, 'black_cross', 'black_cross_050', 'Мир на молитвата', 'Днес е празник с черен кръст: {feast_title}. В тишината на молитвата душата намира силата да продължи напред с надежда.', true),
  ('bg', null, null, 'black_cross', 'black_cross_051', 'Смирено сърце', 'Днес е празник с черен кръст: {feast_title}. Смирението отваря пътя към мир и укрепва връзката на човека с Бога.', true),
  ('bg', null, null, 'black_cross', 'black_cross_052', 'Живяна вяра', 'Днес е празник с черен кръст: {feast_title}. Храни душата си чрез молитва и добри дела. Вярата се укрепва чрез живот.', true),
  ('bg', null, null, 'black_cross', 'black_cross_053', 'Доброта, която ражда', 'Днес е празник с черен кръст: {feast_title}. Прави доброто без да очакваш награда. Бог вижда всяко дело, направено с любов.', true),
  ('bg', null, null, 'black_cross', 'black_cross_054', 'Време за душата', 'Днес е празник с черен кръст: {feast_title}. Намери няколко минути тишина и молитва. Душата се нуждае от приближаване до Бога.', true),
  ('bg', null, null, 'black_cross', 'black_cross_055', 'Светлината на вярата', 'Днес е празник с черен кръст: {feast_title}. Вярата носи светлина в мислите и мир в сърцето. Запази я жива чрез молитва.', true),
  ('bg', null, null, 'black_cross', 'black_cross_056', 'Нежно сърце', 'Днес е празник с черен кръст: {feast_title}. Нежността и добротата сближават хората и запазват мира в душата.', true),
  ('bg', null, null, 'black_cross', 'black_cross_057', 'Върви с надежда', 'Днес е празник с черен кръст: {feast_title}. Поверявай на Бога тревогите си и върви напред с доверие и търпение.', true),
  ('bg', null, null, 'black_cross', 'black_cross_058', 'Мир във всеки крачка', 'Днес е празник с черен кръст: {feast_title}. Нека мирът ръководи решенията ти и запази вярата във всички обстоятелства.', true),
  ('bg', null, null, 'black_cross', 'black_cross_059', 'Смирена любов', 'Днес е празник с черен кръст: {feast_title}. Обичай без гордост и помагай без шум. Искрената доброта носи мир на сърцето.', true),
  ('bg', null, null, 'black_cross', 'black_cross_060', 'Остани постоянен', 'Днес е празник с черен кръст: {feast_title}. Продължавай да търсиш доброто чрез молитва, търпение и любов. Бог укрепва вярващата душа.', true),
  ('bg', null, null, 'black_cross', 'black_cross_061', 'Думите с полза', 'Днес е празник с черен кръст: {feast_title}. Избирай днес думи, които носят мир и насърчение. Доброто започва с начина, по който говорим.', true),
  ('bg', null, null, 'black_cross', 'black_cross_062', 'Запази тишината', 'Днес е празник с черен кръст: {feast_title}. Не позволявай бързането да смущава душата ти. В тишина и молитва сърцето намира укрепление.', true),
  ('bg', null, null, 'black_cross', 'black_cross_063', 'Благодарно сърце', 'Днес е празник с черен кръст: {feast_title}. Благодари на Бога за всички благословии, които получаваш. Благодарността носи мир и надежда.', true),
  ('bg', null, null, 'black_cross', 'black_cross_064', 'Бъди близо', 'Днес е празник с черен кръст: {feast_title}. Добро слово и отворено сърце могат да донесат утешение на изпитващия.', true),
  ('bg', null, null, 'black_cross', 'black_cross_065', 'Молитва и мир', 'Днес е празник с черен кръст: {feast_title}. Поверявай на Бога началото на този ден. Молитвата носи спокойствие и укрепление.', true),
  ('bg', null, null, 'black_cross', 'black_cross_066', 'Нежност на сърцето', 'Днес е празник с черен кръст: {feast_title}. Нежността е знак на сърце, което се доверява на Бога и търси мира.', true),
  ('bg', null, null, 'black_cross', 'black_cross_067', 'Мисъл към небето', 'Днес е празник с черен кръст: {feast_title}. Издигни мислите си към Бога и запази вярата жива във всяка минута.', true),
  ('bg', null, null, 'black_cross', 'black_cross_068', 'Силата на добротата', 'Днес е празник с черен кръст: {feast_title}. Не подценявай силата на едно добро дело. Любовта, проявена към ближния, носи светлина.', true),
  ('bg', null, null, 'black_cross', 'black_cross_069', 'Душа на стража', 'Днес е празник с черен кръст: {feast_title}. Внимавай над мислите си и запази сърцето си чисто чрез молитва.', true),
  ('bg', null, null, 'black_cross', 'black_cross_070', 'Мир и търпение', 'Днес е празник с черен кръст: {feast_title}. Търпението запазва спокойствието на душата и помага да остане близо до Бога.', true),
  ('bg', null, null, 'black_cross', 'black_cross_071', 'Непоклатима вяра', 'Днес е празник с черен кръст: {feast_title}. Остани постоянен във вярата и не спирай да търсиш Божията воля във всичко.', true),
  ('bg', null, null, 'black_cross', 'black_cross_072', 'Полезен ден', 'Днес е празник с черен кръст: {feast_title}. Живей този ден със смирение и доброта. Всяко добро дело е дар за ближния.', true),
  ('bg', null, null, 'black_cross', 'black_cross_073', 'Смирена любов', 'Днес е празник с черен кръст: {feast_title}. Обичай без да търсиш награда. Бог вижда всяко дело, направено от чисто сърце.', true),
  ('bg', null, null, 'black_cross', 'black_cross_074', 'Душевен мир', 'Днес е празник с черен кръст: {feast_title}. Намери няколко минути тишина и молитва. Бог носи мир на тези, които Го търсят.', true),
  ('bg', null, null, 'black_cross', 'black_cross_075', 'Върви с мир', 'Днес е празник с черен кръст: {feast_title}. Поверявай този ден на Бога и върви напред с вяра, търпение и любов.', true),
  ('bg', null, null, 'black_cross', 'black_cross_076', 'Започни с молитва', 'Днес е празник с черен кръст: {feast_title}. Поверявай този ден на Бога и запази сърцето си в мир. Молитвата укрепва душата.', true),
  ('bg', null, null, 'black_cross', 'black_cross_077', 'Запази надеждата', 'Днес е празник с черен кръст: {feast_title}. Каквито и да са изпитанията, не губи надежда. Бог остава близо до тези, които Го търсят.', true),
  ('bg', null, null, 'black_cross', 'black_cross_078', 'Смирено сърце', 'Днес е празник с черен кръст: {feast_title}. Проявявай доброта и разбиране към околните. Милостинята носи мир и радост на душата.', true),
  ('bg', null, null, 'black_cross', 'black_cross_079', 'Тишина и молитва', 'Днес е празник с черен кръст: {feast_title}. Намери няколко минути тишина пред Бога. В тишина душата се укрепва.', true),
  ('bg', null, null, 'black_cross', 'black_cross_080', 'Вяра и мир', 'Днес е празник с черен кръст: {feast_title}. Нека вярата ръководи решенията ти. Бог осветява стъпките на смирените.', true),
