  ('el', null, null, 'black_cross', 'black_cross_117', 'Ειλικρινής ευγνωμοσύνη', 'Σήμερα είναι γιορτή με μαύρο σταυρό: {feast_title}. Ευχαρίστησε για κάθε καλό που έχεις λάβει. Μια ευγνώμον καρδιά παραμένει γεμάτη ειρήνη και ελπίδα.', true),
  ('el', null, null, 'black_cross', 'black_cross_118', 'Να είσαι στήριγμα', 'Σήμερα είναι γιορτή με μαύρο σταυρό: {feast_title}. Μια ενθάρρυνση που λέγεται στην κατάλληλη στιγμή μπορεί να φέρει παρηγοριά. Δώσε την με αγάπη.', true),
  ('el', null, null, 'black_cross', 'black_cross_119', 'Ο δρόμος της ειρήνης', 'Σήμερα είναι γιορτή με μαύρο σταυρό: {feast_title}. Διάλεξε την ειρήνη αντί της αναστάτωσης και την καλοσύνη αντί της σκληρότητας. Ο Θεός ενδυναμώνει αυτή την επιλογή.', true),
  ('el', null, null, 'black_cross', 'black_cross_120', 'Κοντά στον Κύριο', 'Σήμερα είναι γιορτή με μαύρο σταυρό: {feast_title}. Ζήσε αυτή τη μέρα με προσευχή, ταπεινοφροσύνη και πίστη. Ο Θεός παραμένει η στήριξη αυτών που τον αναζητούν.', true),
  ('el', null, null, 'daily', 'daily_001', 'Ξεκίνα με προσευχή', 'Εμπιστεύσου αυτήν την ημέρα στον Θεό. Η προσευχή φέρνει ειρήνη στην καρδιά και ενισχύει τα βήματα προς το καλό.', true),
  ('el', null, null, 'daily', 'daily_002', 'Διατήρησε την ειρήνη της καρδιάς', 'Ακόμη και μέσα στις ανησυχίες, αναζήτησε την ηρεμία που προέρχεται από την εγγύτητα στον Θεό. Αυτός δεν εγκαταλείπει εκείνους που τον αναζητούν.', true),
  ('el', null, null, 'daily', 'daily_003', 'Να είσαι ευγνώμον', 'Ευχαρίστησε τον Θεό για τα δώρα που έχεις λάβει. Η ευγνωμοσύνη φωτίζει την ψυχή και φέρνει ειρήνη.', true),
  ('el', null, null, 'daily', 'daily_004', 'Ένα βήμα προς το καλό', 'Κάνε σήμερα ένα καλό με καθαρή καρδιά. Η αγάπη εκδηλώνεται μέσα από απλές και ειλικρινείς πράξεις.', true),
  ('el', null, null, 'daily', 'daily_005', 'Αμετάβλητη ελπίδα', 'Μην αφήνεις την απογοήτευση να κυριαρχεί στην καρδιά σου. Βάλε την ελπίδα σου στον Θεό και προχώρα με υπομονή.', true),
  ('el', null, null, 'daily', 'daily_006', 'Λόγια με απαλότητα', 'Μίλα με καλοσύνη και υπομονή. Ένας λόγος που λέγεται με αγάπη μπορεί να φέρει ηρεμία σε εκείνον που είναι δίπλα σου.', true),
  ('el', null, null, 'daily', 'daily_007', 'Ο Θεός σε ενισχύει', 'Σε κάθε δοκιμασία, αναζήτησε τη στήριξη του Κυρίου μέσω της προσευχής. Αυτός δίνει δύναμη στην ψυχή που εμπιστεύεται σε Αυτόν.', true),
  ('el', null, null, 'daily', 'daily_008', 'Δούλεψε με χαρά', 'Εκπλήρωσε τα καθήκοντά σου με καθαρή καρδιά. Κάθε πράξη που γίνεται με πίστη είναι μια καλή μαρτυρία.', true),
  ('el', null, null, 'daily', 'daily_009', 'Η ειρήνη αρχίζει στην καρδιά', 'Διατήρησε την ηρεμία της ψυχής και μην απαντάς το κακό με κακό. Η απαλότητα φέρνει καλούς καρπούς.', true),
  ('el', null, null, 'daily', 'daily_010', 'Σήκωσε το βλέμμα', 'Όταν οι ανησυχίες γίνονται βαριές, σήκωσε τη σκέψη σου προς τον Θεό. Η προσευχή φέρνει ενίσχυση και ελπίδα.', true),
  ('el', null, null, 'daily', 'daily_011', 'Να είσαι υπομονετικός', 'Η υπομονή είναι έργο της καρδιάς. Μην βιάζεσαι να κρίνεις, αλλά διατήρησε την ειρήνη και την καλοσύνη.', true),
  ('el', null, null, 'daily', 'daily_012', 'Εμπιστοσύνη στον Κύριο', 'Ακόμη και αν δεν βλέπεις όλο το δρόμο, προχώρα με πίστη. Ο Θεός καθοδηγεί τα βήματα του ταπεινού.', true),
  ('el', null, null, 'daily', 'daily_013', 'Διατήρησε την καλοσύνη', 'Μια καλή καρδιά φέρνει φως γύρω της. Μην κουράζεσαι να κάνεις το καλό με ταπεινότητα.', true),
  ('el', null, null, 'daily', 'daily_014', 'Μια στιγμή προσευχής', 'Σταμάτησε για λίγα λεπτά και προσευχήσου. Ο Θεός ακούει την καρδιά που τον αναζητά με ειλικρίνεια.', true),
  ('el', null, null, 'daily', 'daily_015', 'Ευλογημένη ημέρα', 'Ζήσε αυτήν την ημέρα με πίστη, υπομονή και αγάπη. Κάθε αρχή είναι μια νέα ευκαιρία να κάνεις το καλό.', true),
  ('el', null, null, 'daily', 'daily_016', 'Ξεκίνα με ειρήνη', 'Διάλεξε να ξεκινήσεις αυτήν την ημέρα με μια ήρεμη καρδιά. Ο Θεός ενισχύει εκείνον που τον αναζητά με πίστη.', true),
  ('el', null, null, 'daily', 'daily_017', 'Διατήρησε την ελπίδα', 'Ακόμη και όταν ο δρόμος φαίνεται δύσκολος, μην χάσεις την ελπίδα. Ο Θεός εργάζεται υπομονετικά στη ζωή του καθενός.', true),
  ('el', null, null, 'daily', 'daily_018', 'Αγάπα τον πλησίον', 'Δείξε καλοσύνη με απλές χειρονομίες και ειλικρινείς λόγους. Η αγάπη φέρνει κοντά τις καρδιές και φέρνει ειρήνη.', true),
  ('el', null, null, 'daily', 'daily_019', 'Μια ταπεινή καρδιά', 'Η ταπεινότητα ανοίγει το δρόμο προς την ηρεμία της ψυχής. Ο Θεός δέχεται την προσευχή που λέγεται με ειλικρίνεια.', true),
  ('el', null, null, 'daily', 'daily_020', 'Αναζήτησε την ηρεμία', 'Άφησε για λίγα λεπτά τις ανησυχίες στην άκρη και σήκωσε τη σκέψη σου προς τον Θεό. Η προσευχή φέρνει ανάπαυση στην καρδιά.', true),
  ('el', null, null, 'daily', 'daily_021', 'Κάνε το καλό', 'Μην αναβάλλεις μια καλή πράξη όταν μπορείς να την εκπληρώσεις σήμερα. Η καλοσύνη καρποφορεί με τον καιρό.', true),
  ('el', null, null, 'daily', 'daily_022', 'Μείνε σταθερός', 'Η πίστη ενισχύεται μέσω της υπομονής και της προσευχής. Συνέχισε να προχωράς με εμπιστοσύνη.', true),
  ('el', null, null, 'daily', 'daily_023', 'Καθαρή χαρά', 'Δέξου με ευγνωμοσύνη τις ευλογίες κάθε ημέρας. Μια ευγνώμονη καρδιά διατηρεί την ειρήνη.', true),
  ('el', null, null, 'daily', 'daily_024', 'Μίλα με απαλότητα', 'Οι λέξεις που λέγονται με αγάπη μπορούν να φέρουν παρηγοριά. Διάλεξε πάντα την καλοσύνη αντί της σκληρότητας.', true),
  ('el', null, null, 'daily', 'daily_025', 'Μια νέα αρχή', 'Κάθε ημέρα είναι μια νέα ευκαιρία να διορθώσεις ό,τι έχεις κάνει λάθος και να πλησιάσεις περισσότερο τον Θεό.', true),
  ('el', null, null, 'daily', 'daily_026', 'Εμπιστοσύνη και ειρήνη', 'Άφησε την ανησυχία στα χέρια του Θεού. Αυτός γνωρίζει τις ανάγκες της καρδιάς σου.', true),
  ('el', null, null, 'daily', 'daily_027', 'Σταμάτησε λίγο', 'Βρες λίγα λεπτά για προσευχή και περισυλλογή. Η ψυχή ενισχύεται στην ησυχία.', true),
  ('el', null, null, 'daily', 'daily_028', 'Διασπορά καλοσύνης', 'Μια χειρονομία που γίνεται από αγάπη μπορεί να φέρει ελπίδα σε εκείνον που έχει ανάγκη. Μην κουράζεσαι να κάνεις το καλό.', true),
  ('el', null, null, 'daily', 'daily_029', 'Ζωντανή πίστη', 'Διατήρησε την πίστη σε όλες τις περιστάσεις. Ο Θεός παραμένει κοντά σε εκείνους που τον αναζητούν.', true),
  ('el', null, null, 'daily', 'daily_030', 'Ειρήνη και ευγνωμοσύνη', 'Κλείσε κάθε ημέρα με ευχαριστία προς τον Θεό. Η ευγνωμοσύνη φέρνει ηρεμία και ενισχύει την ψυχή.', true),
  ('el', null, null, 'daily', 'daily_031', 'Μείνε στην προσευχή', 'Ακόμη και μια σύντομη προσευχή, που λέγεται με ειλικρίνεια, φέρνει ηρεμία και ενίσχυση στην ψυχή.', true),
  ('el', null, null, 'daily', 'daily_032', 'Καρδιά γεμάτη ειρήνη', 'Μην αφήνεις την βιασύνη να ταράξει την ψυχή σου. Η ειρήνη διατηρείται μέσω της πίστης και της υπομονής.', true),
  ('el', null, null, 'daily', 'daily_033', 'Να είσαι φως', 'Μια καλή πράξη και ένας ήπιος λόγος μπορούν να φέρουν χαρά στους γύρω σου. Δώσε τους με αγάπη.', true),
  ('el', null, null, 'daily', 'daily_034', 'Ο Θεός καθοδηγεί', 'Πριν από κάθε απόφαση, αναζήτησε τη βοήθεια του Θεού. Αυτός φωτίζει το μυαλό και ενισχύει την καρδιά.', true),
  ('el', null, null, 'daily', 'daily_035', 'Ευχαρίστησε πάντα', 'Η ευγνωμοσύνη αλλάζει τον τρόπο που βλέπουμε κάθε ημέρα. Ευχαρίστησε τον Θεό για όλα τα δώρα που έχεις λάβει.', true),
  ('el', null, null, 'daily', 'daily_036', 'Διατήρησε την καλοσύνη', 'Η καλοσύνη που δείχνεις στον πλησίον είναι μια μαρτυρία της πίστης που βιώνεται με ειλικρίνεια.', true),
  ('el', null, null, 'daily', 'daily_037', 'Μια ήρεμη ψυχή', 'Αναζήτησε την ηρεμία που προέρχεται από την εγγύτητα στον Θεό. Αυτή δίνει δύναμη σε κάθε δοκιμασία.', true),
  ('el', null, null, 'daily', 'daily_038', 'Η υπομονή καρποφορεί', 'Μην απογοητεύεσαι αν οι απαντήσεις καθυστερούν. Η υπομονή ενισχύει την ψυχή και διατηρεί την ειρήνη.', true),
  ('el', null, null, 'daily', 'daily_039', 'Κοίτα με ελπίδα', 'Κάθε ημέρα φέρνει μια νέα ευκαιρία να κάνεις το καλό και να πλησιάσεις περισσότερο τον Θεό.', true),
  ('el', null, null, 'daily', 'daily_040', 'Η ειρήνη του Χριστού', 'Δέξου με ταπεινή καρδιά την ειρήνη που δίνει ο Χριστός σε εκείνους που τον αναζητούν με πίστη.', true),
  ('el', null, null, 'daily', 'daily_041', 'Συγχώρεσε με αγάπη', 'Η συγχώρεση απελευθερώνει την καρδιά από το βάρος της δυσαρέσκειας και ανοίγει το δρόμο προς την ειρήνη.', true),
  ('el', null, null, 'daily', 'daily_042', 'Χρήσιμα λόγια', 'Διάλεξε λόγια που φέρνουν ενθάρρυνση και καλοσύνη. Ο ήπιος λόγος φέρνει κοντά τις καρδιές.', true),
  ('el', null, null, 'daily', 'daily_043', 'Ελπίδα για κάθε ημέρα', 'Όσο δύσκολος κι αν φαίνεται ο δρόμος, ο Θεός παραμένει στήριγμα για εκείνους που τον αναζητούν.', true),
  ('el', null, null, 'daily', 'daily_044', 'Ζήσε με ταπεινότητα', 'Η ταπεινότητα φέρνει ηρεμία στην ψυχή και βοηθά να δεχτείς τη θέληση του Θεού με εμπιστοσύνη.', true),
  ('el', null, null, 'daily', 'daily_045', 'Ειρήνη στην ψυχή', 'Εμπιστεύσου αυτήν την ημέρα στον Θεό και προχώρα με πίστη, υπομονή και ευγνωμοσύνη.', true),
  ('el', null, null, 'daily', 'daily_046', 'Χάρη σε κάθε ημέρα', 'Δέξου κάθε ημέρα ως δώρο του Θεού. Ζήσε την με πίστη, καλοσύνη και ειρήνη.', true),
  ('el', null, null, 'daily', 'daily_047', 'Μια ευγνώμον καρδιά', 'Η ευγνωμοσύνη προς τον Θεό φέρνει ηρεμία και ενισχύει την ψυχή σε όλες τις περιστάσεις.', true),
  ('el', null, null, 'daily', 'daily_048', 'Μείνε σταθερός', 'Μην εγκαταλείπεις την προσευχή, ακόμη και αν ο δρόμος φαίνεται δύσκολος. Ο Θεός είναι κοντά σε εκείνους που τον αναζητούν.', true),
  ('el', null, null, 'daily', 'daily_049', 'Ξεκίνα με το καλό', 'Διάλεξε να κάνεις το πρώτο βήμα προς το καλό από την αρχή της ημέρας. Οι καλές πράξεις φέρνουν ειρήνη στην καρδιά.', true),
  ('el', null, null, 'daily', 'daily_050', 'Αναζήτησε τη σοφία', 'Ζήτησε από τον Θεό να φωτίσει τις σκέψεις σου και να καθοδηγήσει τα βήματά σου στον σωστό δρόμο.', true),
  ('el', null, null, 'daily', 'daily_051', 'Η ειρήνη διατηρείται', 'Μην αφήνεις την αναστάτωση να καταλάβει την ψυχή σου. Η προσευχή και η υπομονή φέρνουν ηρεμία.', true),
  ('el', null, null, 'daily', 'daily_052', 'Αγάπη μέσω πράξεων', 'Η αληθινή αγάπη φαίνεται στην φροντίδα, την υπομονή και την καλοσύνη προς τον πλησίον.', true),
  ('el', null, null, 'daily', 'daily_053', 'Μια χρήσιμη ημέρα', 'Κάνε ό,τι έχεις να εκπληρώσεις με καθαρή καρδιά και με εμπιστοσύνη στη βοήθεια του Θεού.', true),
  ('el', null, null, 'daily', 'daily_054', 'Κοίτα μπροστά', 'Μην μένεις κολλημένος στα λάθη του παρελθόντος. Με μετάνοια και ελπίδα μπορείς να προχωρήσεις μπροστά.', true),
  ('el', null, null, 'daily', 'daily_055', 'Η απαλότητα φέρνει ειρήνη', 'Μια ήπια καρδιά διασπείρει ηρεμία στην οικογένεια και στους γύρω.', true),
  ('el', null, null, 'daily', 'daily_056', 'Διατήρησε την πίστη', 'Η πίστη ενισχύεται μέσω της προσευχής, της υπομονής και της εμπιστοσύνης στη φροντίδα του Θεού.', true),
  ('el', null, null, 'daily', 'daily_057', 'Κάνε χώρο για ηρεμία', 'Σταμάτησε για λίγα λεπτά και άφησε την προσευχή να σου φέρει ειρήνη στην ψυχή.', true),
  ('el', null, null, 'daily', 'daily_058', 'Η χαρά του καλού', 'Χάρηκες κάθε φορά που μπορείς να κάνεις ένα καλό. Η αγάπη που δείχνεις στον πλησίον δεν μένει χωρίς καρπό.', true),
  ('el', null, null, 'daily', 'daily_059', 'Μείνε κοντά στον Θεό', 'Σε κάθε περίσταση, γύρισε την καρδιά σου προς τον Θεό. Αυτός είναι η στήριξη εκείνων που τον αναζητούν.', true),
  ('el', null, null, 'daily', 'daily_060', 'Ειρήνη και φως', 'Είθε αυτή η ημέρα να ζήσει με ειρήνη, πίστη και ειλικρινή επιθυμία να κάνεις το καλό.', true),
  ('el', null, null, 'daily', 'daily_061', 'Εμπιστοσύνη σε κάθε βήμα', 'Προχώρα με πίστη και άφησε τις ανησυχίες στα χέρια του Θεού. Αυτός ενισχύει την ψυχή που τον αναζητά.', true),
  ('el', null, null, 'daily', 'daily_062', 'Μείνε στην ειρήνη', 'Μην επιτρέπεις στην ανησυχία να κυριαρχεί στην καρδιά σου. Η προσευχή φέρνει ηρεμία και ελπίδα.', true),
  ('el', null, null, 'daily', 'daily_063', 'Κάνε το καλό με χαρά', 'Κάθε καλή πράξη που γίνεται από αγάπη φέρνει φως στη ζωή σου και στους γύρω.', true),
  ('el', null, null, 'daily', 'daily_064', 'Μια στιγμή περισυλλογής', 'Σταμάτησε για λίγα λεπτά και μίλα με τον Θεό. Αυτός ακούει την προσευχή που λέγεται με ειλικρίνεια.', true),
  ('el', null, null, 'daily', 'daily_065', 'Η δύναμη της υπομονής', 'Η υπομονή διατηρεί την ειρήνη της καρδιάς και σε βοηθά να περάσεις με σοφία μέσα από τις δοκιμασίες.', true),
  ('el', null, null, 'daily', 'daily_066', 'Καρδιά γεμάτη πίστη', 'Η ειλικρινής πίστη φέρνει θάρρος και ενίσχυση. Ο Θεός δεν εγκαταλείπει εκείνους που τον αναζητούν.', true),
  ('el', null, null, 'daily', 'daily_067', 'Δώσε καλοσύνη', 'Μια απλή χειρονομία που γίνεται με αγάπη μπορεί να αλλάξει τη μέρα ενός ανθρώπου. Μην σταματάς να κάνεις το καλό.', true),
  ('el', null, null, 'daily', 'daily_068', 'Κοίτα με εμπιστοσύνη', 'Ακόμη και αν δεν καταλαβαίνεις όλα τα πράγματα, προχώρα με ελπίδα και προσευχή.', true),
  ('el', null, null, 'daily', 'daily_069', 'Η ειρήνη του Θεού', 'Άφησε την ειρήνη του Θεού να καθοδηγεί τις σκέψεις σου και να ενισχύει την ψυχή σου.', true),
  ('el', null, null, 'daily', 'daily_070', 'Ζήσε με απαλότητα', 'Η απαλότητα φέρνει ηρεμία στην οικογένεια και στους ανθρώπους. Διάλεξε πάντα τον καλό λόγο.', true),
  ('el', null, null, 'daily', 'daily_071', 'Αναζήτησε το καλό', 'Κάθε ημέρα προσφέρει την ευκαιρία να κάνεις ένα καλό. Εκπλήρωσέ το με καθαρή καρδιά.', true),
  ('el', null, null, 'daily', 'daily_072', 'Ο Θεός είναι κοντά', 'Σε κάθε περίσταση, σήκωσε την καρδιά σου προς τον Θεό. Αυτός παραμένει στήριγμα για τους πιστούς.', true),
  ('el', null, null, 'daily', 'daily_073', 'Η χαρά της ευγνωμοσύνης', 'Ευχαρίστησε για τα μικρά και τα μεγάλα πράγματα. Η ευγνωμοσύνη φέρνει ειρήνη και ενισχύει την πίστη.', true),
  ('el', null, null, 'daily', 'daily_074', 'Μια χρήσιμη ημέρα', 'Εκπλήρωσε το καθήκον σου με υπομονή και καλοσύνη. Το έργο που γίνεται με καθαρή καρδιά φέρνει καρπούς.', true),
  ('el', null, null, 'daily', 'daily_075', 'Προχώρα με ελπίδα', 'Εμπιστεύσου αυτήν την ημέρα στον Θεό και προχώρα με ειρήνη, πίστη και αγάπη.', true),
  ('el', null, null, 'daily', 'daily_076', 'Διατήρησε την ταπεινότητα', 'Η ταπεινότητα φέρνει ειρήνη στην ψυχή και την πλησιάζει στον Θεό. Προχώρα με καθαρή καρδιά.', true),
  ('el', null, null, 'daily', 'daily_077', 'Μια ανοιχτή καρδιά', 'Δέξου κάθε άνθρωπο με καλοσύνη και σεβασμό. Η ειλικρινής αγάπη φέρνει φως στην καθημερινή ζωή.', true),
  ('el', null, null, 'daily', 'daily_078', 'Αρχή με ελπίδα', 'Εμπιστεύσου αυτήν την ημέρα στον Θεό. Αυτός ενισχύει εκείνους που τον αναζητούν με πίστη.', true),
  ('el', null, null, 'daily', 'daily_079', 'Λόγια που οικοδομούν', 'Διάλεξε να μιλήσεις με απαλότητα και σοφία. Ένας καλός λόγος μπορεί να φέρει ειρήνη σε μια ταραγμένη καρδιά.', true),
  ('el', null, null, 'daily', 'daily_080', 'Υπομονή σε όλα', 'Μην βιάζεσαι να θυμώσεις. Η υπομονή διατηρεί την ηρεμία της ψυχής και ενισχύει την αγάπη.', true),
  ('el', null, null, 'daily', 'daily_081', 'Η χαρά της πίστης', 'Η πίστη φέρνει θάρρος στις δοκιμασίες και ειρήνη στην καρδιά. Μείνε κοντά στον Θεό κάθε ημέρα.', true),
  ('el', null, null, 'daily', 'daily_082', 'Να είσαι ελεήμον', 'Δείξε κατανόηση και καλοσύνη στους γύρω. Η ελεημοσύνη είναι ένα όμορφο έργο της καρδιάς.', true),
  ('el', null, null, 'daily', 'daily_083', 'Καθαρή σκέψη', 'Διατήρησε το μυαλό και την καρδιά σου στραμμένα προς το καλό. Η προσευχή φωτίζει τις σκέψεις.', true),
  ('el', null, null, 'daily', 'daily_084', 'Ζήσε με ειρήνη', 'Μην αφήνεις την βιασύνη να σου κλέψει την ηρεμία. Ο Θεός δίνει ειρήνη σε εκείνους που τον αναζητούν με ειλικρίνεια.', true),
  ('el', null, null, 'daily', 'daily_085', 'Καθημερινή ευγνωμοσύνη', 'Ευχαρίστησε τον Θεό για κάθε καλό που έχεις λάβει. Μια ευγνώμον καρδιά παραμένει γεμάτη ελπίδα.', true),
  ('el', null, null, 'daily', 'daily_086', 'Να είσαι στήριγμα', 'Ένας καλός λόγος ή μια απλή χειρονομία μπορεί να φέρει παρηγοριά στον πλησίον. Κάνε το καλό με αγάπη.', true),
  ('el', null, null, 'daily', 'daily_087', 'Εμπιστεύσου τις ανησυχίες', 'Άφησε μπροστά στον Θεό ό,τι σε πιέζει. Η προσευχή φέρνει δύναμη και ηρεμία.', true),
  ('el', null, null, 'daily', 'daily_088', 'Το φως της καλοσύνης', 'Η καλοσύνη που δείχνεται με ταπεινότητα θερμαίνει τις καρδιές και φέρνει ειρήνη ανάμεσα στους ανθρώπους.', true),
  ('el', null, null, 'daily', 'daily_089', 'Ακολούθησε το καλό', 'Διάλεξε κάθε ημέρα ό,τι φέρνει την ψυχή πιο κοντά στον Θεό. Οι καλές πράξεις καρποφορούν με τον καιρό.', true),
  ('el', null, null, 'daily', 'daily_090', 'Ειρήνη και πίστη', 'Ξεκίνα και κλείσε την ημέρα με προσευχή. Ο Θεός παραμένει η ελπίδα και η ενίσχυση εκείνων που τον αγαπούν.', true),
  ('el', null, null, 'daily', 'daily_091', 'Αναζήτησε την ειρήνη', 'Διατήρησε την ειρήνη της καρδιάς ακόμη και στις πολυάσχολες στιγμές. Ο Θεός ενισχύει την ψυχή που τον αναζητά.', true),
  ('el', null, null, 'daily', 'daily_092', 'Προσευχή με ελπίδα', 'Ανάβα μια ειλικρινή προσευχή και βάλε την εμπιστοσύνη σου στον Θεό. Αυτός γνωρίζει τις ανάγκες της καρδιάς σου.', true),
  ('el', null, null, 'daily', 'daily_093', 'Μια καλή πράξη', 'Μην χάσεις την ευκαιρία να κάνεις το καλό. Μια απλή χειρονομία μπορεί να φέρει χαρά και παρηγοριά.', true),
  ('el', null, null, 'daily', 'daily_094', 'Σταθερή πίστη', 'Μείνε κοντά στον Θεό σε όλες τις περιστάσεις. Η πίστη ενισχύει την ψυχή μέρα με τη μέρα.', true),
  ('el', null, null, 'daily', 'daily_095', 'Απλότητα και υπομονή', 'Απάντησε με απαλότητα και διατήρησε την υπομονή. Έτσι διατηρείται η ειρήνη ανάμεσα στους ανθρώπους.', true),
  ('el', null, null, 'daily', 'daily_096', 'Ευχαρίστησε τον Θεό', 'Βρες κάθε ημέρα έναν λόγο για να ευχαριστήσεις. Η ευγνωμοσύνη φέρνει φως στην καρδιά.', true),
  ('el', null, null, 'daily', 'daily_097', 'Μια ήρεμη καρδιά', 'Άφησε τις ανησυχίες μπροστά στον Θεό και προχώρα με εμπιστοσύνη. Αυτός είναι η στήριξή σου.', true),
  ('el', null, null, 'daily', 'daily_098', 'Ζήσε με καλοσύνη', 'Η καλοσύνη που δείχνεται στον πλησίον είναι μια όμορφη μαρτυρία της πίστης που βιώνεται με ειλικρίνεια.', true),
  ('el', null, null, 'daily', 'daily_099', 'Αρχή με πίστη', 'Κάθε ημέρα είναι μια νέα ευκαιρία να βαδίσεις στον δρόμο του καλού και να παραμείνεις κοντά στον Θεό.', true),
  ('el', null, null, 'daily', 'daily_100', 'Η ειρήνη της ψυχής', 'Αναζήτησε πρώτα την ηρεμία της καρδιάς μέσω της προσευχής. Ο Θεός φέρνει ειρήνη σε εκείνους που τον αναζητούν.', true),
  ('el', null, null, 'daily', 'daily_101', 'Να είσαι ευγνώμον', 'Ευχαρίστησε για κάθε στιγμή και για κάθε αγαθό που έχεις λάβει. Μια ευγνώμον καρδιά παραμένει γεμάτη ειρήνη.', true),
  ('el', null, null, 'daily', 'daily_102', 'Μείνε κοντά', 'Μην αφήνεις καμία μέρα να περάσει χωρίς μια σκέψη προς τον Θεό. Η προσευχή ενισχύει την ψυχή.', true),
  ('el', null, null, 'daily', 'daily_103', 'Το φως της πίστης', 'Η πίστη φωτίζει τα βήματα εκείνου που προχωρά με ταπεινότητα και ελπίδα μπροστά στον Θεό.', true),
  ('el', null, null, 'daily', 'daily_104', 'Δώσε ειρήνη', 'Να είσαι πηγή ειρήνης με τα λόγια και τις πράξεις σου. Η καλοσύνη φέρνει ηρεμία γύρω σου.', true),
  ('el', null, null, 'daily', 'daily_105', 'Προχώρα με τον Θεό', 'Εμπιστεύσου τον Θεό την αρχή και το τέλος αυτής της ημέρας. Αυτός παραμένει η ελπίδα των πιστών.', true),
  ('el', null, null, 'daily', 'daily_106', 'Μείνε με ελπίδα', 'Ακόμα και όταν αντιμετωπίζεις δυσκολίες, κράτησε την εμπιστοσύνη σου στον Θεό. Αυτός δίνει δύναμη στην καρδιά που προσεύχεται.', true),
  ('el', null, null, 'daily', 'daily_107', 'Η χαρά του καλού', 'Κάθε καλή πράξη που γίνεται με ταπεινότητα φέρνει ειρήνη στην ψυχή και χαρά στον πλησίον.', true),
  ('el', null, null, 'daily', 'daily_108', 'Μια ειλικρινής προσευχή', 'Ξεκίνα αυτή την ημέρα με μια προσευχή από την καρδιά. Ο Θεός ακούει εκείνους που τον αναζητούν με πίστη.', true),
  ('el', null, null, 'daily', 'daily_109', 'Διατήρησε την καλοσύνη', 'Μην αφήνεις την κούραση να σβήσει την καλοσύνη σου. Μια ήρεμη καρδιά φέρνει φως γύρω της.', true),
  ('el', null, null, 'daily', 'daily_110', 'Πίστη και υπομονή', 'Προχώρα χωρίς φόβο. Ο Θεός εργάζεται στην κατάλληλη στιγμή για το καλό της ψυχής.', true),
  ('el', null, null, 'daily', 'daily_111', 'Ειρήνη κάθε μέρα', 'Διάλεξε την ηρεμία αντί της αναταραχής. Η προσευχή διατηρεί την ειρήνη στην καρδιά.', true),
  ('el', null, null, 'daily', 'daily_112', 'Να είσαι κοντά', 'Να είσαι δίπλα σε εκείνους που χρειάζονται μια καλή λέξη. Η αγάπη εκδηλώνεται μέσα από απλές πράξεις.', true),
  ('el', null, null, 'daily', 'daily_113', 'Εμπιστεύσου τα πάντα', 'Βάλε μπροστά στον Θεό τις ανησυχίες και τα σχέδιά σου. Αυτός καθοδηγεί τα βήματα του πιστού.', true),
  ('el', null, null, 'daily', 'daily_114', 'Μια καθαρή καρδιά', 'Διατήρησε τις σκέψεις σου καθαρές και αναζήτησε το καλό σε όλα. Έτσι ενδυναμώνεται η ψυχή.', true),
  ('el', null, null, 'daily', 'daily_115', 'Ζήσε με απλότητα', 'Η απλότητα φέρνει ειρήνη στην οικογένεια και ανάμεσα στους ανθρώπους. Να είσαι υπομονετικός και κατανοητικός.', true),
  ('el', null, null, 'daily', 'daily_116', 'Ευγνωμοσύνη και ειρήνη', 'Ευχαρίστησε τον Θεό για κάθε αρχή και για κάθε αγαθό που έχεις λάβει με αγάπη.', true),
  ('el', null, null, 'daily', 'daily_117', 'Προχώρα με εμπιστοσύνη', 'Μην φοβάσαι το άγνωστο. Ο Θεός παραμένει κοντά σε εκείνους που ελπίζουν σε Αυτόν.', true),
  ('el', null, null, 'daily', 'daily_118', 'Κάνε το καλό πάντα', 'Μην κουράζεσαι να κάνεις το καλό με καθαρή καρδιά. Κάθε καλή πράξη φέρνει καρπό στην ώρα της.', true),
  ('el', null, null, 'daily', 'daily_119', 'Ησυχία για την ψυχή', 'Βρες λίγες στιγμές σιωπής και προσευχής. Ο Θεός φέρνει ειρήνη στην ταπεινή καρδιά.', true),
  ('el', null, null, 'daily', 'daily_120', 'Η ευλογία κάθε ημέρας', 'Δέξου κάθε μέρα με πίστη, ευγνωμοσύνη και αγάπη. Ο Θεός είναι η στήριξη εκείνων που τον αναζητούν.', true),
  ('el', null, null, 'fasting', 'fasting_001', 'Νηστεία με καθαρή καρδιά', 'Κανονισμός νηστείας: {fasting_note}. Η νηστεία είναι καιρός προσευχής, ταπεινότητας και εγγύτητας στον Θεό. Διατήρησε την ειρήνη στην καρδιά.', true),
