  ('ka', null, null, 'black_cross', 'black_cross_043', 'კეთილდღეობა უსიტყვოდ', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. კეთილი საქმეები არ საჭიროებს დიდებას. ღმერთი ხედავს სიყვარულს, რომელიც საიდუმლოდ კეთდება.', true),
  ('ka', null, null, 'black_cross', 'black_cross_044', 'მშვიდობის გზა', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. მტკიცედ იარე მშვიდობის გზით, მოთმინებით და რწმენით. ღმერთი ახლოსაა მდაბალ ადამიანებთან.', true),
  ('ka', null, null, 'black_cross', 'black_cross_045', 'რწმენა და ლოცვა', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. მიენდო ეს დღე ღმერთს და შენახე შენი გული მშვიდობაში ლოცვით.', true),
  ('ka', null, null, 'black_cross', 'black_cross_046', 'ლოცვით დღე', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. დაიწყე ეს დღე ლოცვით და შენახე შენი გული ახლოს ღმერთთან. ის მშვიდობას აძლევს მორწმუნის სულს.', true),
  ('ka', null, null, 'black_cross', 'black_cross_047', 'მოთმინება და რწმენა', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. არ დაიბნეოდი გამოცდების წინაშე. მოთმინება და რწმენა ყოველ დღე აძლიერებს სულს.', true),
  ('ka', null, null, 'black_cross', 'black_cross_048', 'წმინდა აზრები', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. შენ უნდა შეინარჩუნო შენი გონება და გული სიკეთეზე მიმართული. ლოცვა ნათელს ხდის მორწმუნის გზას.', true),
  ('ka', null, null, 'black_cross', 'black_cross_049', 'მეზობელთან ახლოს', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. კეთილი საქმე და კარგი სიტყვა შეიძლება მოიტანოს სიმშვიდე. მიაწვდე ისინი სიყვარულით და თავმდაბლობით.', true),
  ('ka', null, null, 'black_cross', 'black_cross_050', 'ლოცვის მშვიდობა', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. ლოცვის სიმშვიდეში, სული პოულობს ძალას, რომ წინ წავიდეს იმედით.', true),
  ('ka', null, null, 'black_cross', 'black_cross_051', 'მდაბალი გული', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. მდაბლობა გზას ხსნის მშვიდობისკენ და აძლიერებს ადამიანის კავშირს ღმერთთან.', true),
  ('ka', null, null, 'black_cross', 'black_cross_052', 'ცოცხალი რწმენა', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. მოამარაგე შენი სული ლოცვით და კეთილი საქმეებით. რწმენა ძლიერდება ცხოვრებით.', true),
  ('ka', null, null, 'black_cross', 'black_cross_053', 'კეთილდღეობა ნაყოფს მოაქვს', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. კეთილი საქმის კეთება არ უნდა მოელოდეს ჯილდოს. ღმერთი ხედავს ყოველ საქმეს, რომელიც კეთდება სიყვარულით.', true),
