  ('ka', null, null, 'black_cross', 'black_cross_079', '安静与祷告', '今天是黑十字节日：{feast_title}。在上帝面前找一些安静的时刻。在宁静中，灵魂得到力量。', true),
  ('ka', null, null, 'black_cross', 'black_cross_080', '信仰与和平', '今天是黑十字节日：{feast_title}。让信仰引导你的决定。上帝照亮谦卑者的脚步。', true),
  ('ka', null, null, 'black_cross', 'black_cross_081', 'სიყვარულით სავსე სიტყვები', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. საუბარი კეთილად და მოთმინებით. კარგი სიტყვა შეიძლება მოიტანოს სიმშვიდე გულში.', true),
  ('ka', null, null, 'black_cross', 'black_cross_082', 'იყავი მადლიერი', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. მადლობა ღმერთს თითოეული მიღებული საჩუქრისთვის. მადლიერება მოაქვს სიმშვიდეს და ნდობას.', true),
  ('ka', null, null, 'black_cross', 'black_cross_083', 'კეთილობის გზა', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. აირჩიე სიკეთე ყოველ შეხვედრაში და ყოველ გადაწყვეტილებაში. სიყვარული ჩანს საქმეებით.', true),
  ('ka', null, null, 'black_cross', 'black_cross_084', 'გულმოდგინე', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. ყურადღება მიაქციე შენს აზრებს და შეინახე ლოცვა გულთან ახლოს.', true),
  ('ka', null, null, 'black_cross', 'black_cross_085', 'დარჩი თავმდაბალი', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. თავმდაბლობა მოაქვს მშვიდობას სულში და ეხმარება მიიღოს ყველაფერი ღმერთზე ნდობით.', true),
  ('ka', null, null, 'black_cross', 'black_cross_086', 'სიყვარულით ახლოს', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. იყავი ახლოს იმ ადამიანებთან, ვისაც სჭირდება მხარდაჭერა. სიყვარულით სავსე გულმა მოაქვს ნუგეში.', true),
  ('ka', null, null, 'black_cross', 'black_cross_087', 'ღმერთის მშვიდობა', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. ეძებე მშვიდობა, რომელიც მოდის ღმერთისგან და შეინახე იგი ლოცვით და მოთმინებით.', true),
  ('ka', null, null, 'black_cross', 'black_cross_088', 'დღეს კეთილი საქმეები', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. ნუ დააყოვნებ კეთილი საქმის გაკეთებას ახლა. ღმერთი ხედავს თითოეულ საქმეს, რომელიც კეთილი სიყვარულით არის გაკეთებული.', true),
  ('ka', null, null, 'black_cross', 'black_cross_089', 'სარწმუნოების შუქი', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. სარწმუნოება ანათებს სულის გზას და მოაქვს ძალა ნებისმიერ სიტუაციაში.', true),
  ('ka', null, null, 'black_cross', 'black_cross_090', 'მშვიდობის დღე', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. იცხოვრე ეს დღე თავმდაბლობით, ლოცვით და კეთილობით. ღმერთი აძლიერებს მორწმუნის სულს.', true),
  ('ka', null, null, 'black_cross', 'black_cross_091', 'დარჩი მშვიდობაში', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. მიენდო ღმერთს შენს Sorgen-ებს. მშვიდი გულით ლოცვა მოაქვს ძალას.', true),
