  ('ka', null, null, 'black_cross', 'black_cross_096', 'მცირე თავმდაბლობა', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. თავმდაბლობა მოაქვს სიმშვიდეს და უახლოვებს სულს ღმერთს. წინ მიდი ნდობით.', true),
  ('ka', null, null, 'black_cross', 'black_cross_097', 'იყავი შუქი', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. კეთილობით და მოთმინებით შეგიძლია იმედის მოტანა გარშემო მყოფებისთვის. ნუ შეწყვეტ კეთილი საქმის კეთებას.', true),
  ('ka', null, null, 'black_cross', 'black_cross_098', 'მუშა სარწმუნოება', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. მიეცი სარწმუნოებას გამოჩნდეს თითოეულ საქმეში და თითოეულ სიტყვაში, რომელიც სიყვარულით არის ნათქვამი.', true),
  ('ka', null, null, 'black_cross', 'black_cross_099', 'მშვიდი გული', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. ეძებე შერიგება და კეთილობა ყველაფერში. ღმერთი აკურთხებს მშვიდობის მოყვარულ სულს.', true),
  ('ka', null, null, 'black_cross', 'black_cross_100', 'სრული ნდობა', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. მაშინაც კი, როდესაც ყველაფერს ვერ ხვდები, მიენდო ღმერთს.', true),
  ('ka', null, null, 'black_cross', 'black_cross_101', 'მშვიდობის წუთი', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. გაჩერდი რამდენიმე წუთით და ილოცე. გულმშვიდობა არის ძვირფასი საჩუქარი.', true),
  ('ka', null, null, 'black_cross', 'black_cross_102', 'სიყვარული და მოთმინება', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. აჩვენე მოთმინება და სიყვარული შენს შეხვედრებში. კეთილობა აძლიერებს ადამიანებს შორის კავშირს.', true),
  ('ka', null, null, 'black_cross', 'black_cross_103', 'დარჩი ახლოს', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. ნუ დაუშვებ, რომ დღე გავიდეს ლოცვის გარეშე. ღმერთი ახლოს არის მათთან, ვინც მას ეძებს.', true),
  ('ka', null, null, 'black_cross', 'black_cross_104', 'სარწმუნოების მშვიდობა', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. სარწმუნოება მოაქვს სიმშვიდეს Sorgen-ების შუაში. მიენდო ღმერთს თითოეული ნაბიჯისთვის.', true),
  ('ka', null, null, 'black_cross', 'black_cross_105', 'ბედნიერი დღე', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. იცხოვრე ეს დღე ლოცვით, თავმდაბლობით და კეთილობით. ღმერთი აძლიერებს სულს, რომელიც მას უყვარს.', true),
  ('ka', null, null, 'black_cross', 'black_cross_106', 'გული ლოცვაში', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. დაიწყე ეს დღე ლოცვით და ნდობით. ღმერთი აძლიერებს სულს, რომელიც მას გულწრფელად ეძებს.', true),
  ('ka', null, null, 'black_cross', 'black_cross_107', 'ეძებე სიკეთე', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. ყოველ შეხვედრაში გაქვს შესაძლებლობა აირჩიო კეთილობა. გააკეთე ეს ნაბიჯი თავმდაბალი გულით.', true),
  ('ka', null, null, 'black_cross', 'black_cross_108', 'მშვიდობა და კეთილობა', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. კეთილობა ინარჩუნებს გულმშვიდობას და მოაქვს გაგება ადამიანებს შორის.', true),
  ('ka', null, null, 'black_cross', 'black_cross_109', 'მტკიცე სარწმუნოება', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. დარჩი ახლოს ღმერთთან ლოცვით და მოთმინებით. ის არის მორწმუნეების მხარდაჭერა.', true),
  ('ka', null, null, 'black_cross', 'black_cross_110', 'დრო სულისთვის', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. გაჩერდი რამდენიმე წუთით და მიმართე შენი აზრები ღმერთისკენ. ლოცვა მოაქვს მშვიდობას.', true),
  ('ka', null, null, 'black_cross', 'black_cross_111', 'მდაბალი კეთილობა', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. კეთილი საქმეები გააკეთე ჯილდოს გარეშე. ღმერთი ხედავს თითოეულ საქმეს, რომელიც კეთილი სიყვარულით არის გაკეთებული.', true),
  ('ka', null, null, 'black_cross', 'black_cross_112', 'შენახე იმედი', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. თუნდაც მძიმე დღეებში, ნუ დაკარგავ ნდობას. ღმერთი ხელმძღვანელობს იმ სულს, რომელიც ლოცულობს.', true),
  ('ka', null, null, 'black_cross', 'black_cross_113', 'სიყვარული საქმეებში', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. აჩვენე სიყვარული მოთმინებით, კეთილობით და გაგებით. ასე ძლიერდება მშვიდობა ადამიანებს შორის.', true),
  ('ka', null, null, 'black_cross', 'black_cross_114', 'მშვიდობა და სარწმუნოება', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. მიეცი ლოცვას, რომ მოიტანოს მშვიდობა და შეინახე შენი გული ახლოს ღმერთთან.', true),
  ('ka', null, null, 'black_cross', 'black_cross_115', 'მომხმარებელი დღე', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. შეასრულე შენი მოვალეობები თავმდაბლობით და სარწმუნოებით. ღმერთი აკურთხებს გულწრფელად გაკეთებულ შრომას.', true),
  ('ka', null, null, 'black_cross', 'black_cross_116', 'აზრი ღმერთისკენ', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. მიმართე შენი აზრები ღმერთისკენ და შეინახე მშვიდობა სულში მთელი დღის განმავლობაში.', true),
  ('ka', null, null, 'black_cross', 'black_cross_117', ' sincera მადლობა', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. მადლობა თითოეული მიღებული სიკეთისთვის. მადლიერი გული რჩება მშვიდობით და იმედით.', true),
  ('ka', null, null, 'black_cross', 'black_cross_118', 'იყავი მხარდაჭერა', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. დროულად ნათქვამი წახალისება შეიძლება მოიტანოს ნუგეში. მიეცი ეს სიყვარულით.', true),
  ('ka', null, null, 'black_cross', 'black_cross_119', 'მშვიდობის გზა', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. აირჩიე მშვიდობა შეწუხების ნაცვლად და კეთილობა სიმკაცრის ნაცვლად. ღმერთი აძლიერებს ამ არჩევანს.', true),
  ('ka', null, null, 'black_cross', 'black_cross_120', 'ღმერთთან ახლოს', 'დღეს არის შავი ჯვრის დღესასწაული: {feast_title}. იცხოვრე ეს დღე ლოცვით, თავმდაბლობით და სარწმუნოებით. ღმერთი რჩება იმათ მხარდაჭერა, ვინც მას ეძებს.', true),
  ('ka', null, null, 'daily', 'daily_001', 'ლოცვით დაიწყე', 'ამ დღე მიაწვდე ღმერთს. ლოცვა მშვიდობას მოაქვს გულში და აძლიერებს ნაბიჯებს კეთილისკენ.', true),
  ('ka', null, null, 'daily', 'daily_002', 'გულის მშვიდობა შეინარჩუნე', 'თუნდაც Sorgen-ის وسط, ეძებე სიმშვიდე, რომელიც ღმერთთან სიახლოვიდან მოდის. ის არ ტოვებს მათ, ვინც მას ეძებს.', true),
  ('ka', null, null, 'daily', 'daily_003', 'მადლიერი იყავი', 'მადლობა ღმერთს მიღებული საჩუქრებისთვის. მადლიერება სული განათლებს და მშვიდობას მოაქვს.', true),
  ('ka', null, null, 'daily', 'daily_004', 'კეთილისკენ ერთი ნაბიჯი', 'დღეს კეთილი საქმე გააკეთე სუფთა გულით. სიყვარული გამოჩნდება უბრალო და გულწრფელ საქმეებში.', true),
  ('ka', null, null, 'daily', 'daily_005', 'მტკიცე იმედი', 'არ დაუშვა, რომ discouragement-მა შენი გული დაიპყროს. შენი იმედი ღმერთში დააყენე და მოთმინებით განაგრძე.', true),
  ('ka', null, null, 'daily', 'daily_006', 'სიყვარულით ნათქვამი სიტყვები', 'ლაპარაკი კეთილად და მოთმინებით. სიყვარულით ნათქვამი სიტყვა შეიძლება მშვიდობა მოიტანოს შენს გვერდით მყოფისთვის.', true),
  ('ka', null, null, 'daily', 'daily_007', 'ღმერთი გაწვდავს', 'ყოველგვარ გამოცდაში, ეძებე უფლის მხარდაჭერა ლოცვით. ის ძალას აძლევს სულს, რომელიც მას ენდობა.', true),
  ('ka', null, null, 'daily', 'daily_008', 'ბედნიერებით იმუშაო', 'შენი მოვალეობები სუფთა გულით შეასრულე. კეთილი საქმე, რომელიც კეთილსინდისიერად გაკეთდება, კარგი მოწმეა.', true),
  ('ka', null, null, 'daily', 'daily_009', 'მშვიდობა იწყება გულში', 'შენიშვნა შენს სულში და არ უპასუხო ბოროტებას ბოროტებით. სიმშვიდე კარგი ნაყოფი მოაქვს.', true),
  ('ka', null, null, 'daily', 'daily_010', 'მზერა მაღლა', 'როდესაც Sorgen-ები მძიმე ხდება, შენი აზრი ღმერთისკენ აწიე. ლოცვა გაწვდავს და იმედს მოაქვს.', true),
  ('ka', null, null, 'daily', 'daily_011', 'მოთმინებული იყავი', 'მოთმინება გულის საქმეა. არ მოიწადინე განსჯა, არამედ მშვიდობა და კეთილდღეობა შეინარჩუნე.', true),
  ('ka', null, null, 'daily', 'daily_012', 'ღმერთში ნდობა', 'თუნდაც მთელი გზა არ გინახავს, წინ მიდი რწმენით. ღმერთი ხელმძღვანელობს თავმდაბალი ადამიანის ნაბიჯებს.', true),
  ('ka', null, null, 'daily', 'daily_013', 'კეთილდღეობა შეინარჩუნე', 'კეთილი გული გარშემო სინათლეს მოაქვს. არ დაიღალო კეთილი საქმის კეთებით თავმდაბლობით.', true),
  ('ka', null, null, 'daily', 'daily_014', 'ლოცვის ერთი წუთი', 'ჩამოაყენე რამდენიმე წუთი და ილოცე. ღმერთი ისმენს გულს, რომელიც მას გულწრფელად ეძებს.', true),
  ('ka', null, null, 'daily', 'daily_015', 'ბედნიერი დღე', 'ეს დღე რწმენით, მოთმინებით და სიყვარულით გაატარეთ. ყოველი დასაწყისი არის ახალი შესაძლებლობა კეთილის გაკეთების.', true),
  ('ka', null, null, 'daily', 'daily_016', 'მშვიდობით დაიწყე', 'აირჩიე, რომ ეს დღე მშვიდი გულით დაიწყო. ღმერთი გაწვდავს იმათ, ვინც მას რწმენით ეძებს.', true),
  ('ka', null, null, 'daily', 'daily_017', 'იმედის შენარჩუნება', 'თუნდაც გზა რთული იყოს, იმედი არ დაკარგო. ღმერთი მოთმინებით მუშაობს თითოეული ადამიანის ცხოვრებაში.', true),
