  ('ka', null, null, 'daily', 'daily_073', 'მადლიერების სიხარული', 'მადლობა მცირე და დიდ საქმეებზე. მადლიერება მშვიდობას მოაქვს და რწმენას აძლიერებს.', true),
  ('ka', null, null, 'daily', 'daily_074', 'მომხმარებელი დღე', 'შეასრულე შენი მოვალეობა მოთმინებით და კეთილდღეობით. გულწრფელად გაკეთებული საქმე ნაყოფს მოაქვს.', true),
  ('ka', null, null, 'daily', 'daily_075', 'იმედით მიდი', 'ამ დღე მიაწვდე ღმერთს და მშვიდობით, რწმენით და სიყვარულით წინ მიდი.', true),
  ('ka', null, null, 'daily', 'daily_076', 'მდაბლობა შეინარჩუნე', 'მდაბლობა მშვიდობას მოაქვს სულში და ახლოსაა ღმერთთან. წინ მიდი სუფთა გულით.', true),
  ('ka', null, null, 'daily', 'daily_077', 'გული გახსნილი', 'მიიღე ყოველი ადამიანი კეთილად და პატივით. გულწრფელი სიყვარული სინათლეს მოაქვს ყოველდღიურ ცხოვრებაში.', true),
  ('ka', null, null, 'daily', 'daily_078', 'იმედით დაწყება', 'ამ დღე მიაწვდე ღმერთს. ის გაწვდავს იმათ, ვინც მას რწმენით ეძებს.', true),
  ('ka', null, null, 'daily', 'daily_079', 'სიტყვები, რომლებიც აშენებენ', 'აირჩიე, რომ კეთილად და სიბრძნით ილაპარაკო. კეთილი სიტყვა შეიძლება მშვიდობა მოიტანოს შეწუხებულ გულში.', true),
  ('ka', null, null, 'daily', 'daily_080', 'ყველაფერში მოთმინება', 'არ მოიწადინე გაბრაზება. მოთმინება მშვიდობას ინარჩუნებს სულში და სიყვარულს აძლიერებს.', true),
  ('ka', null, null, 'daily', 'daily_081', 'რწმენის სიხარული', 'რწმენა გაწვდავს Courage-ით გამოცდებში და მშვიდობას გულში. ყოველდღე ახლოს დარჩი ღმერთთან.', true),
  ('ka', null, null, 'daily', 'daily_082', 'მილოსიერი იყავი', 'აჩვენე გაგება და კეთილდღეობა გარშემო. მილოსიერება გულის მშვენიერი საქმეა.', true),
  ('ka', null, null, 'daily', 'daily_083', 'წმინდა აზრი', 'შენარჩუნე შენი გონება და გული კეთილისკენ. ლოცვა აზრებს განათლებს.', true),
  ('ka', null, null, 'daily', 'daily_084', 'მშვიდობით იცხოვრე', 'არ დაუშვა, რომ სისწრაფემ შენი სიმშვიდე მოიპაროს. ღმერთი მშვიდობას აძლევს იმათ, ვინც მას გულწრფელად ეძებს.', true),
  ('ka', null, null, 'daily', 'daily_085', 'ყოველდღიური მადლობა', 'მადლობა ღმერთს ყოველი მიღებული სიკეთისათვის. მადლიერების გული იმედით სავსეა.', true),
  ('ka', null, null, 'daily', 'daily_086', 'მხარდაჭერა იყავი', 'კეთილი სიტყვა ან უბრალო ჟესტი შეიძლება მეზობლად მღელვარება მოიტანოს. კეთილი საქმის კეთება სიყვარულით.', true),
  ('ka', null, null, 'daily', 'daily_087', 'გ Sorgen-ები მიაწვდე', 'დატოვე ღმერთის წინაშე ის, რაც გაწუხებს. ლოცვა ძალას და სიმშვიდეს მოაქვს.', true),
  ('ka', null, null, 'daily', 'daily_088', 'კეთილდღეობის სინათლე', 'მდაბლობით გამოჩენილი კეთილდღეობა გულებს თბილობს და მშვიდობას მოაქვს ადამიანებს შორის.', true),
  ('ka', null, null, 'daily', 'daily_089', 'კეთილის გაწვდვა', 'ყოველდღე აირჩიე ის, რაც სულს ღმერთთან დაახლოებს. კეთილი საქმეები დროთა განმავლობაში ნაყოფს მოაქვს.', true),
  ('ka', null, null, 'daily', 'daily_090', 'მშვიდობა და რწმენა', 'დღის დაწყება და დასრულება ლოცვით. ღმერთი რჩება იმათთვის, ვინც მას უყვარს, იმედად და ძალად.', true),
  ('ka', null, null, 'daily', 'daily_091', 'მშვიდობის ძიება', 'შენარჩუნე გულის მშვიდობა თუნდაც გადატვირთულ მომენტებში. ღმერთი აძლიერებს სულს, რომელიც მას ეძებს.', true),
  ('ka', null, null, 'daily', 'daily_092', 'იმედით ლოცვა', 'წამოაყენე გულწრფელი ლოცვა და შენი ნდობა ღმერთში. ის იცის შენი გულის საჭიროებები.', true),
  ('ka', null, null, 'daily', 'daily_093', 'კეთილი საქმე', 'არ დაკარგო შესაძლებლობა კეთილი საქმის გაკეთების. უბრალო ჟესტი შეიძლება სიხარული და მღელვარება მოიტანოს.', true),
  ('ka', null, null, 'daily', 'daily_094', 'მტკიცე რწმენა', 'ყოველგვარ გარემოებაში ახლოს დარჩი ღმერთთან. რწმენა ყოველდღიურად სულს აძლიერებს.', true),
  ('ka', null, null, 'daily', 'daily_095', 'ბრძანება და მოთმინება', 'პასუხი კეთილად და შეინარჩუნე მოთმინება. ასე ინარჩუნებს მშვიდობას ადამიანებს შორის.', true),
  ('ka', null, null, 'daily', 'daily_096', 'მადლობა ღმერთს', 'ყოველდღე მოძებნე მადლიერების მიზეზი. მადლიერება სინათლეს მოაქვს გულში.', true),
  ('ka', null, null, 'daily', 'daily_097', 'მშვიდი გული', 'დატოვე Sorgen-ები ღმერთის წინაშე და წინ მიდი რწმენით. ის არის შენი მხარდაჭერა.', true),
  ('ka', null, null, 'daily', 'daily_098', 'კეთილდღეობით იცხოვრე', 'მეზობლად კეთილდღეობა რწმენის გულწრფელი ცხოვრების მშვენიერი მოწმეა.', true),
  ('ka', null, null, 'daily', 'daily_099', 'რწმენით დაწყება', 'ყოველი დღე არის ახალი შესაძლებლობა, რომ კეთილის გზაზე წახვიდე და ღმერთთან ახლოს დარჩე.', true),
  ('ka', null, null, 'daily', 'daily_100', 'სულის მშვიდობა', 'პირველ რიგში, მოიძიე გულის სიმშვიდე ლოცვით. ღმერთი მშვიდობას მოაქვს იმათთვის, ვინც მას ეძებს.', true),
  ('ka', null, null, 'daily', 'daily_101', 'იყავი მადლიერ', 'მადლობა თითოეული წამისთვის და თითოეული მიღებული სიკეთისთვის. მადლიერი გული მშვიდობით რჩება.', true),
  ('ka', null, null, 'daily', 'daily_102', 'მოახლოება', 'არ დაუშვა, რომ დღე ჩაივლის ღმერთზე ფიქრის გარეშე. ლოცვა სულს აძლიერებს.', true),
  ('ka', null, null, 'daily', 'daily_103', '信仰的光', '信仰照亮了谦卑和希望走在上帝面前的人的脚步。', true),
  ('ka', null, null, 'daily', 'daily_104', 'მშვიდობის გაწვდვა', 'იყავი მშვიდობის წყარო შენი სიტყვებით და საქმეებით. კეთილდღეობა მშვიდობას მოაქვს.', true),
  ('ka', null, null, 'daily', 'daily_105', 'ღმერთთან ერთად სიარული', 'ამ დღის დასაწყისსა და დასასრულში ღმერთს მიენდო. ის რჩება მორწმუნეების იმედად.', true),
  ('ka', null, null, 'daily', 'daily_106', 'იმედით დარჩენა', 'თუნდაც სირთულეების წინაშე, შენს რწმენას ღმერთში შეინარჩუნე. ის ძალას აძლევს ლოცულ მ გულს.', true),
  ('ka', null, null, 'daily', 'daily_107', 'კეთილის სიხარული', 'ყოველი კეთილი საქმე, რომელიც თავმდაბლობით კეთდება, მშვიდობას მოაქვს სულში და სიხარულს მეზობელთან.', true),
  ('ka', null, null, 'daily', 'daily_108', ' sincera ლოცვა', 'ამ დღის დაწყება გულიდან ლოცვით. ღმერთი ისმენს მათ, ვინც რწმენით ეძებს.', true),
  ('ka', null, null, 'daily', 'daily_109', 'კეთილდღეობის შენარჩუნება', 'არ დაუშვა, რომ დაღლილობამ შენი კეთილდღეობა შეამციროს. მშვიდი გული შუქს მოაქვს მის გარშემო.', true),
  ('ka', null, null, 'daily', 'daily_110', '信仰与耐心', '勇往直前，不要害怕。上帝在适当的时候为灵魂的益处而工作。', true),
  ('ka', null, null, 'daily', 'daily_111', '每一天的平安', '选择宁静而不是烦扰。祷告保持内心的平安。', true),
  ('ka', null, null, 'daily', 'daily_112', 'მოახლოება', 'იყავი მათთან, ვინც კარგ სიტყვას საჭიროებს. სიყვარული გამოჩნდება უბრალო საქმეებით.', true),
  ('ka', null, null, 'daily', 'daily_113', 'ყველაფერი ღმერთს მიენდო', 'გთხოვ, ღმერთს მიაწვდე შენი Sorgen და გეგმები. ის ხელმძღვანელობს მორწმუნის ნაბიჯებს.', true),
  ('ka', null, null, 'daily', 'daily_114', 'წმინდა გული', 'შენ უნდა შეინარჩუნო შენი აზრები წმინდა და ეძებდე სიკეთეს ყველაფერში. ასე ძლიერდება სული.', true),
  ('ka', null, null, 'daily', 'daily_115', 'მშვიდობით ცხოვრება', 'მშვიდობა ოჯახში და ადამიანებს შორის. იყავი მოთმინებული და გაგებით.', true),
  ('ka', null, null, 'daily', 'daily_116', 'მადლობა და მშვიდობა', 'მადლობა ღმერთს თითოეული დასაწყისისთვის და თითოეული მიღებული სიკეთისთვის სიყვარულით.', true),
  ('ka', null, null, 'daily', 'daily_117', 'დარწმუნებით წასვლა', 'არ შეგეშინდეს უცნობი. ღმერთი ახლოსაა მათთან, ვინც იმედს მასში დებს.', true),
  ('ka', null, null, 'daily', 'daily_118', 'ყოველთვის კეთილი საქმის კეთება', 'არ დაიღალო კეთილი საქმის კეთებაში წმინდა გულით. ყოველი კეთილი საქმე თავის დროზე მოაქვს ნაყოფს.', true),
  ('ka', null, null, 'daily', 'daily_119', 'სულის მშვიდობა', 'გაითვალისწინე რამდენიმე წუთი სიჩუმისა და ლოცვისთვის. ღმერთი მშვიდობას მოაქვს თავმდაბალ გულში.', true),
  ('ka', null, null, 'daily', 'daily_120', 'ყოველი დღის კურთხევა', 'მიიღე ყოველი დღე რწმენით, მადლიერებით და სიყვარულით. ღმერთი არის იმათ მხარდაჭერა, ვინც მას ეძებს.', true),
  ('ka', null, null, 'fasting', 'fasting_001', 'წმინდა გულით მარხვა', 'მარხვის წესები: {fasting_note}. მარხვა არის ლოცვის, თავმდაბლობის და ღმერთთან ახლოს ყოფნის დრო. შეინარჩუნე მშვიდობა გულში.', true),
  ('ka', null, null, 'fasting', 'fasting_002', 'ლოცვა და თავშეკავება', 'მარხვის წესები: {fasting_note}. გააერთიანე თავშეკავება ლოცვასთან და კეთილგანწყობასთან. ასე მარხვა მოაქვს ნაყოფს სულში.', true),
