  ('ka', null, null, 'fasting', 'fasting_004', 'კეთილგანწყობა სიყვარულით', 'მარხვის წესები: {fasting_note}. მარხვა გაატარეთ კეთილგანწყობით და ყურადღებით ახლობლის მიმართ. კეთილგანწყობა აძლიერებს რწმენას.', true),
  ('ka', null, null, 'fasting', 'fasting_005', 'თავშეკავება და მშვიდობა', 'მარხვის წესები: {fasting_note}. შეინარჩუნე ზომიერება აზრებში, სიტყვებში და საქმეებში. ღმერთი აძლიერებს თავმდაბალ სულს.', true),
  ('ka', null, null, 'fasting', 'fasting_006', 'ღმერთთან ახლოს', 'მარხვის წესები: {fasting_note}. გამოიყენე ეს დღე მეტი ლოცვისა და სიმშვიდისთვის. ღმერთი იღებს გულწრფელ გულს.', true),
  ('ka', null, null, 'fasting', 'fasting_007', 'გულის სიწმინდე', 'მარხვის წესები: {fasting_note}. მარხვა არის გულისთვისაც. ეძებ მშვიდობას, მოთმინებას და სიყვარულს.', true),
  ('ka', null, null, 'fasting', 'fasting_008', 'დრო სულიისთვის', 'მარხვის წესები: {fasting_note}. შეწყვიტე ჩვეულებრივი სიჩქარე და გააკეთე ადგილი ლოცვისთვის. სულს სჭირდება ღმერთთან სიახლოვე.', true),
  ('ka', null, null, 'fasting', 'fasting_009', 'მუშა რწმენა', 'მარხვის წესები: {fasting_note}. დაუშვი მარხვა იყოს კეთილი საქმეების და კეთილ სიტყვების თანმხლები.', true),
  ('ka', null, null, 'fasting', 'fasting_010', 'მშვიდობა ლოცვით', 'მარხვის წესები: {fasting_note}. ლოცვა მოაქვს გულში სიმშვიდეს და აძლიერებს სულს მარხვის დროს.', true),
  ('ka', null, null, 'fasting', 'fasting_011', 'მშვიდობა და მოთმინება', 'მარხვის წესები: {fasting_note}. შეინარჩუნე მშვიდობა ყველა შეხვედრაში. თავშეკავება ჩანს იმაში, როგორ ვლაპარაკობთ.', true),
  ('ka', null, null, 'fasting', 'fasting_012', 'მდაბალი გული', 'მარხვის წესები: {fasting_note}. ღმერთი სიამოვნებით იღებს მდაბალ გულს და გულწრფელად წარმოთქმულ ლოცვას.', true),
  ('ka', null, null, 'fasting', 'fasting_013', 'სიყვარული და მოწყალება', 'მარხვის წესები: {fasting_note}. ყურადღება მიაქციე ახლობლის საჭიროებებს და გულით გაწვდე. მოწყალება ამშვენებს მარხვას.', true),
  ('ka', null, null, 'fasting', 'fasting_014', 'იმედი და რწმენა', 'მარხვის წესები: {fasting_note}. იცხოვრე ეს დღე ღმერთზე ნდობით. ის აძლიერებს სულს, რომელიც ეძებს მას.', true),
  ('ka', null, null, 'fasting', 'fasting_015', 'მარხვა სარგებლისთვის', 'მარხვის წესები: {fasting_note}. იყოს ეს მარხვის დღე მეტი ლოცვის, მშვიდობის და ღმერთთან სიახლოვის მომტანი.', true),
  ('ka', null, null, 'fasting', 'fasting_016', 'თავშეკავება სარგებლისთვის', 'მარხვის წესები: {fasting_note}. ჭეშმარიტი თავშეკავება ახლოს მოიყვანს სულს ღმერთთან. შეინარჩუნე ლოცვა და მშვიდობა გულში.', true),
  ('ka', null, null, 'fasting', 'fasting_017', 'მუდმივი ლოცვა', 'მარხვის წესები: {fasting_note}. გააკეთე ადგილი ლოცვისთვის ამ დღეს. ღმერთი აძლიერებს სულს, რომელიც ეძებს მას რწმენით.', true),
  ('ka', null, null, 'fasting', 'fasting_018', 'კეთილგანწყობა და მოწყალება', 'მარხვის წესები: {fasting_note}. გამოიჩინე ყურადღება ახლობლის მიმართ და გულით გაწვდე. მოწყალება მშვენივრად თან ახლავს მარხვას.', true),
  ('ka', null, null, 'fasting', 'fasting_019', 'მშვიდობა სულში', 'მარხვის წესები: {fasting_note}. დაანებე თავი აღელვებას და შეინარჩუნე სიმშვიდე ლოცვით და ღმერთზე ნდობით.', true),
  ('ka', null, null, 'fasting', 'fasting_020', 'აპატიე და მიყვარდე', 'მარხვის წესები: {fasting_note}. გულწრფელად აპატიე და შეინარჩუნე სიყვარული ახლობლის მიმართ. ასე მოაქვს მარხვას ნაყოფი გულში.', true),
  ('ka', null, null, 'fasting', 'fasting_021', 'წმინდა აზრები', 'მარხვის წესები: {fasting_note}. ყურადღება მიაქციე შენს აზრებს და ეძებ კეთილს ყველა საქმეში. გულწმინდა იწყება შიგნიდან.', true),
