  ('ka', null, null, 'fasting', 'fasting_031', 'გული დამშვიდებული', 'მარხვის წესები: {fasting_note}. დაიწყე ეს დღე ლოცვით და აპატიებით. დამშვიდებული გული უფრო ახლოს მიდის ღმერთთან.', true),
  ('ka', null, null, 'fasting', 'fasting_032', 'შეინარჩუნე ზომიერება', 'მარხვის წესები: {fasting_note}. თავშეკავება მოაქვს სიმშვიდეს, როდესაც ის გაწვდილია ლოცვასთან და ახლობლის მიმართ სიყვარულთან.', true),
  ('ka', null, null, 'fasting', 'fasting_033', 'მდაბალი ლოცვა', 'მარხვის წესები: {fasting_note}. ღმერთი იღებს ლოცვას, რომელიც წარმოთქმულია მდაბალი გულით და გულწრფელი სურვილით გამოსწორების.', true),
  ('ka', null, null, 'fasting', 'fasting_034', 'მოწყალე იყავი', 'მარხვის წესები: {fasting_note}. გამოიჩინე კეთილგანწყობა და გაგება გარშემო. მოწყალება მშვენივრად თან ახლავს მარხვის შრომას.', true),
  ('ka', null, null, 'fasting', 'fasting_035', 'მშვიდობა გულში', 'მარხვის წესები: {fasting_note}. დაანებე თავი სიჩქარეს და გააკეთე ადგილი ლოცვისთვის. სულის მშვიდობა არის ძვირფასი საჩუქარი.', true),
