  ('ka', null, null, 'fasting', 'fasting_048', 'მოწყალება გულით', 'მარხვის წესები: {fasting_note}. გაწვდე დახმარების ხელი იმათ, ვინც საჭიროებაშია. მოწყალება ამშვენებს მარხვას.', true),
  ('ka', null, null, 'fasting', 'fasting_049', 'სიწმინდე და იმედი', 'მარხვის წესები: {fasting_note}. წმინდა გულით შეინარჩუნე შენი გული და შენახე იმედი ღმერთში.', true),
  ('ka', null, null, 'fasting', 'fasting_050', 'კეთილგანწყობა სიტყვებში', 'მარხვის წესები: {fasting_note}. აირჩიე პასუხი მოთმინებით და კეთილგანწყობით. თავშეკავება ჩანს სიტყვებში, რომლებიც ვლაპარაკობთ.', true),
  ('ka', null, null, 'fasting', 'fasting_051', 'ღმერთთან ახლოს', 'მარხვის წესები: {fasting_note}. მოიძიე დრო ლოცვისა და სიმშვიდისთვის. ღმერთი ახლოს არის იმათთან, ვინც ეძებს მას.', true),
  ('ka', null, null, 'fasting', 'fasting_052', 'სიყვარული მდაბლად', 'მარხვის წესები: {fasting_note}. კეთილი საქმეები გააკეთე ხმაურის გარეშე და გარეშე დიდების. ღმერთი ხედავს ყოველ საქმეს, რომელიც კეთილი გულით არის გაკეთებული.', true),
  ('ka', null, null, 'fasting', 'fasting_053', 'სულის მშვიდობა', 'მარხვის წესები: {fasting_note}. ნუ დაუშვებ, რომ საზრუნავებმა შენი გული აღელვოს. მიაწვდე ისინი ღმერთს ლოცვით.', true),
  ('ka', null, null, 'fasting', 'fasting_054', 'ცოცხალი რწმენა', 'მარხვის წესები: {fasting_note}. იცხოვრე ეს დღე რწმენით, მოთმინებით და კეთილგანწყობით. ღმერთი აძლიერებს თავმდაბალ სულს.', true),
  ('ka', null, null, 'fasting', 'fasting_055', 'მოწყალე გული', 'მარხვის წესები: {fasting_note}. მიაპყარი ყურადღება ახლობლის მიმართ და დაეხმარე შესაძლებლობის მიხედვით. კეთილგანწყობა დროთა განმავლობაში ნაყოფს მოაქვს.', true),
  ('ka', null, null, 'fasting', 'fasting_056', 'მოთმინება და აპატიება', 'მარხვის წესები: {fasting_note}. შეინარჩუნე მოთმინება და გულით აპატიე. ასე ძლიერდება მარხვის საქმე სულში.', true),
  ('ka', null, null, 'fasting', 'fasting_057', 'დრო სიმშვიდისთვის', 'მარხვის წესები: {fasting_note}. შეწყვიტე რამდენიმე წუთით და ისაუბრე ღმერთთან. ლოცვა მოაქვს მშვიდობას გულში.', true),
  ('ka', null, null, 'fasting', 'fasting_058', 'მარხვა სიხარულით', 'მარხვის წესები: {fasting_note}. იცხოვრე ეს დღე მადლიერებით და თავმდაბლობით. სიხარული მოდის ღმერთთან სიახლოვიდან.', true),
  ('ka', null, null, 'fasting', 'fasting_059', 'კეთილგანწყობის გზა', 'მარხვის წესები: {fasting_note}. თავშეკავება და კეთილგანწყობა ერთად მიდიან. იყავი მხარდაჭერა და ნუგეში გარშემო.', true),
  ('ka', null, null, 'fasting', 'fasting_060', 'ნდობა და მშვიდობა', 'მარხვის წესები: {fasting_note}. დაასრულე ეს დღე ლოცვით და მადლიერებით. ღმერთი აძლიერებს სულს, რომელიც ახლოს რჩება მას.', true),
  ('ka', null, null, 'red_cross', 'red_cross_001', 'წმინდა სიხარულის დღე', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. მიიღე ეს დღე მადლიერებით და ლოცვით. ჭეშმარიტი სიხარული ცხოვრობს ღმერთთან სიახლოვეში.', true),
  ('ka', null, null, 'red_cross', 'red_cross_002', 'შეჩერდი სიჩქარეს', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. დროებით დაანებე Sorgen-ებს და მიმართე შენი გული ღმერთისკენ ლოცვით.', true),
  ('ka', null, null, 'red_cross', 'red_cross_003', 'სირცხვილი თავმდაბლობით', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. პატივი მიეცი ამ დღეს ლოცვით, მშვიდობით და მადლიერებით. ღმერთი ხედავს თავმდაბალ გულს.', true),
  ('ka', null, null, 'red_cross', 'red_cross_004', 'მშვიდობა და შუქი', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. მიიღე ეს დღე სუფთა გულით და შეინახე სარწმუნოების შუქი ყველა საქმეში.', true),
  ('ka', null, null, 'red_cross', 'red_cross_005', 'ღმერთთან ახლოს', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. თუ შეგიძლია, მონაწილეობა მიიღე მსახურებაში და შეინახე გულში ლოცვის სიხარული.', true),
  ('ka', null, null, 'red_cross', 'red_cross_006', 'მადლიერი გული', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. მადლობა ღმერთს მისი სიკეთეებისათვის და იცხოვრე ეს დღე მშვიდობით და სიყვარულით.', true),
  ('ka', null, null, 'red_cross', 'red_cross_007', 'ლოცვა და სიხარული', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. მიეცი ლოცვას, რომ იყოს ამ დღის დასაწყისი. ღმერთი აძლიერებს სულს, რომელიც მას ეძებს.', true),
  ('ka', null, null, 'red_cross', 'red_cross_008', 'მშვიდობა სულში', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. მოიძიე დრო ლოცვისა და განმარტებისათვის. გულმშვიდობა არის ძვირფასი საჩუქარი.', true),
  ('ka', null, null, 'red_cross', 'red_cross_009', 'სარწმუნოება ცოცხალი', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. იცხოვრე ეს დღე სარწმუნოებით და კეთილობით. ყოველი საქმე, რომელიც კეთილი სიყვარულით არის გაკეთებული, მოაქვს ნაყოფი.', true),
  ('ka', null, null, 'red_cross', 'red_cross_010', 'ლოცვის სიხარული', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. აღადგინე შენი გული ღმერთისკენ და შეინახე სიხარული დღეში, რომელიც ღმერთთან ახლოს გატარებული.', true),
  ('ka', null, null, 'red_cross', 'red_cross_011', 'მომხმარებელი დღე', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. შეასრულე ეს დღე მშვიდობით, ლოცვით და კეთილობით. ღმერთი აკურთხებს თავმდაბალ გულს.', true),
  ('ka', null, null, 'red_cross', 'red_cross_012', 'სარწმუნოების შუქი', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. შეინახე ცოცხალი სარწმუნოების შუქი და მიეცი ლოცვას, რომ გაწვდოს შენი ნაბიჯები.', true),
  ('ka', null, null, 'red_cross', 'red_cross_013', 'სიყვარული და მშვიდობა', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. აჩვენე სიყვარული გარშემო მყოფებისთვის და შეინახე სიმშვიდე გულში. ასე პატივს მიაგებ ამ დღეს.', true),
  ('ka', null, null, 'red_cross', 'red_cross_014', 'სუფთა სიხარული', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. მიიღე ეს დღე მადლიერებით და თავმდაბლობით. ღმერთი აძლევს მშვიდობას მორწმუნე სულს.', true),
  ('ka', null, null, 'red_cross', 'red_cross_015', 'ლოცვით ცხოვრება', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. იყოს ეს დღე სავსე ლოცვით, მშვიდობით და მადლიერებით ღმერთის წინაშე.', true),
  ('ka', null, null, 'red_cross', 'red_cross_016', 'სიხარული სარწმუნოებაში', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. იცხოვრე ეს დღე მადლიერი გულით და შეინახე ლოცვა ახლოს. ღმერთი ავსებს სულს მშვიდობით.', true),
  ('ka', null, null, 'red_cross', 'red_cross_017', 'დრო ლოცვისთვის', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. შეჩერდი დროებით და მიმართე შენი აზრები ღმერთისკენ. ლოცვა მოაქვს გულმშვიდობას.', true),
  ('ka', null, null, 'red_cross', 'red_cross_018', 'მშვიდობა და მადლობა', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. მადლობა ღმერთს მისი საჩუქრებისთვის და იცხოვრე ეს დღე თავმდაბლობით და სიხარულით.', true),
  ('ka', null, null, 'red_cross', 'red_cross_019', 'ლოცვით ახლოს', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. თუ შეგიძლია, მონაწილეობა მიიღე მსახურებაში და შეინახე გულში მშვიდობა ღმერთთან შეხვედრის.', true),
  ('ka', null, null, 'red_cross', 'red_cross_020', 'სულის შუქი', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. მიეცი სარწმუნოებას, რომ განათოს შენი აზრები და საქმეები. ღმერთი აძლიერებს სულს, რომელიც მას ეძებს.', true),
  ('ka', null, null, 'red_cross', 'red_cross_021', 'სიყვარულით პატივისცემა', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. პატივი მიეცი ამ დღეს ლოცვით, კეთილობით და მადლიერებით. თავმდაბალი გული მოაქვს ღმერთის დიდებას.', true),
  ('ka', null, null, 'red_cross', 'red_cross_022', 'ლოცვის სიხარული', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. მიმართე შენი გული ღმერთისკენ და შეინახე მშვიდობა, რომელიც მოაქვს გულწრფელ ლოცვას.', true),
  ('ka', null, null, 'red_cross', 'red_cross_023', 'მშვიდობა და სარწმუნოება', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. ამ დღეს ეძებე ღმერთთან სიახლოვე. სულის სიმშვიდე მოდის სარწმუნოებიდან.', true),
  ('ka', null, null, 'red_cross', 'red_cross_024', 'ბედნიერი დღე', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. მიიღე ეს დღე სიხარულით, მშვიდობით და სიყვარულით. ღმერთი აძლიერებს იმათ, ვინც მას ეძებს.', true),
  ('ka', null, null, 'red_cross', 'red_cross_025', 'მადლიერი სული', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. მადლობა ღმერთს მისი заботისთვის და შეინახე მადლიერება ყოველი წამისთვის.', true),
  ('ka', null, null, 'red_cross', 'red_cross_026', 'მშვიდობის გზა', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. მიეცი ღმერთის მშვიდობას, რომ გაწვდოს შენი ნაბიჯები და შეავსოს შენი გული სიხარულით.', true),
  ('ka', null, null, 'red_cross', 'red_cross_027', 'სარწმუნოება და შუქი', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. იცხოვრე ეს დღე ცოცხალი სარწმუნოებით და სუფთა გულით. ლოცვა მოაქვს სულის შუქს.', true),
  ('ka', null, null, 'red_cross', 'red_cross_028', 'სიხარული თავმდაბლობით', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. სიხარული მოიტანე თავმდაბლობით და შეინახე შენი გული ღია ღმერთის ნებას.', true),
  ('ka', null, null, 'red_cross', 'red_cross_029', 'ძლიერება ლოცვაში', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. ეძებე ძალა ლოცვაში და მიენდო ღმერთს ყველა Sorgen-ებისთვის.', true),
  ('ka', null, null, 'red_cross', 'red_cross_030', 'სიყვარული და მშვიდობა', 'დღეს არის წითელი ჯვრის დღესასწაული: {feast_title}. აჩვენე სიყვარული და კეთილობა გარშემო მყოფებისთვის. მშვიდი გული პატივს მიაგებს ამ დღეს.', true),
  ('ka', null, null, 'red_cross', 'red_cross_031', 'სრული ნდობა', 'დღეს წითელი ჯვრის დღესასწაულია: {feast_title}. იარე წინ ღმერთზე ნდობით. ის რჩება მორწმუნე სულის მხარდაჭერა და იმედი.', true),
  ('ka', null, null, 'red_cross', 'red_cross_032', 'მუდმივი ლოცვა', 'დღეს წითელი ჯვრის დღესასწაულია: {feast_title}. ნუ დაუშვებ, რომ ეს დღე ჩაივლის ლოცვის გარეშე. ღმერთი იღებს გულს, რომელიც გულწრფელად ეძებს მას.', true),
  ('ka', null, null, 'red_cross', 'red_cross_033', 'მახლობლობის სიხარული', 'დღეს წითელი ჯვრის დღესასწაულია: {feast_title}. მოახლოება ღმერთთან ლოცვით და შეინარჩუნე სულიერი მშვიდობა, რომელსაც ის გაწვდავს.', true),
  ('ka', null, null, 'red_cross', 'red_cross_034', 'მშვიდობა გულში', 'დღეს წითელი ჯვრის დღესასწაულია: {feast_title}. იყოს ეს დღე მშვიდობა, რწმენა და მადლიერება ღმერთის წინაშე.', true),
  ('ka', null, null, 'red_cross', 'red_cross_035', 'დღე სინათლით', 'დღეს წითელი ჯვრის დღესასწაულია: {feast_title}. იცხოვრე ეს დღე ლოცვით და კეთილგანწყობით. რწმენის სინათლე ხელმძღვანელობს თავმდაბალი ნაბიჯებს.', true),
  ('ka', null, null, 'red_cross', 'red_cross_036', 'გული გახსნილი', 'დღეს წითელი ჯვრის დღესასწაულია: {feast_title}. მიიღე ეს დღე სიყვარულით და მადლიერებით. ღმერთი მოქმედებს იმ სულში, რომელიც ეძებს მას.', true),
  ('ka', null, null, 'red_cross', 'red_cross_037', 'მშვიდობის სიხარული', 'დღეს წითელი ჯვრის დღესასწაულია: {feast_title}. შეინარჩუნე მშვიდობა გულში და გაავრცელე კეთილგანწყობა გარშემო. ეს არის რწმენის მშვენიერი მოწმობა.', true),
  ('ka', null, null, 'red_cross', 'red_cross_038', 'გულწრფელი მადლიერება', 'დღეს წითელი ჯვრის დღესასწაულია: {feast_title}. მადლობა ღმერთს ყველა მიღებული სიკეთისთვის და შეინარჩუნე ცოცხალი იმედი.', true),
  ('ka', null, null, 'red_cross', 'red_cross_039', 'ლოცვა და სინათლე', 'დღეს წითელი ჯვრის დღესასწაულია: {feast_title}. დააბარეთ ეს დღე ღმერთს და მიეცი ლოცვას, რომ გაწვდოს ყოველი ნაბიჯი.', true),
  ('ka', null, null, 'red_cross', 'red_cross_040', 'მშვიდობა და სიხარული', 'დღეს წითელი ჯვრის დღესასწაულია: {feast_title}. დაასრულე ეს დღე მადლიერებით და ლოცვით. ღმერთი ავსებს მშვიდობით იმ გულს, რომელიც ახლოს რჩება მას.', true),
  ('ka', null, null, 'sunday', 'sunday_001', 'ლოცვის დღე', 'დღეს არის კვირა. მიეცი ამ დღეს მეტი დრო ლოცვისთვის და ღმერთთან სიახლოვისთვის. სულის მშვიდობა იწყება მისი ყოფნაში.', true),
  ('ka', null, null, 'sunday', 'sunday_002', 'მშვიდობა ოჯახში', 'დღეს არის კვირა. გაატარეთ ეს დღე სიყვარულით და გაგებით ახლობლებთან. კეთილობა აძლიერებს ადამიანებს შორის კავშირს.', true),
  ('ka', null, null, 'sunday', 'sunday_003', 'ლიტურგიის სიხარული', 'დღეს არის კვირა. თუ შეგიძლია, მონაწილეობა მიიღე წმინდა ლიტურგიაში და შეინახე გულში მოსმენილი სიტყვები.', true),
  ('ka', null, null, 'sunday', 'sunday_004', 'მადლიერი გული', 'დღეს არის კვირა. მადლობა ღმერთს ყველა მიღებული სიკეთისთვის და შეინახე მადლიერება სულში.', true),
  ('ka', null, null, 'sunday', 'sunday_005', 'სულის დასვენება', 'დღეს არის კვირა. დაანებე თავი სიჩქარეს და მოიძიე დრო ლოცვისთვის, სიმშვიდისთვის და ღმერთთან სიახლოვისთვის.', true),
  ('ka', null, null, 'sunday', 'sunday_006', 'სიხარული უფალში', 'დღეს არის კვირა. იცხოვრე ეს დღე მშვიდობით, სარწმუნოებით და სიყვარულით. ღმერთი აძლიერებს სულს, რომელიც მას ეძებს.', true),
  ('ka', null, null, 'sunday', 'sunday_007', 'სარგებლიანი სიტყვა', 'დღეს არის კვირა. გაანებივრე შენი სული მშვენიერი სიტყვების წაკითხვით და შეინახე იგი გულში მთელი დღის განმავლობაში.', true),
  ('ka', null, null, 'sunday', 'sunday_008', 'ბოდიშ და მშვიდობა', 'დღეს არის კვირა. აირჩიე ბოდიშის მოხდა და შერიგება. მშვიდი გული უფრო ადვილად იღებს ღმერთის მშვიდობას.', true),
  ('ka', null, null, 'sunday', 'sunday_009', 'დარჩი ახლოს', 'დღეს არის კვირა. დაიწყე და დაასრულე ეს დღე ლოცვით. ღმერთი ახლოს არის მათთან, ვინც მას ეძებს სარწმუნოებით.', true),
  ('ka', null, null, 'sunday', 'sunday_010', 'სარწმუნოების სიხარული', 'დღეს არის კვირა. იყოს ეს დღე მშვიდობის, იმედისა და სარწმუნოების განმტკიცების მომტანი.', true),
  ('ka', null, null, 'sunday', 'sunday_011', 'გული გახსნილი', 'დღეს არის კვირა. მიიღე ეს დღე თავმდაბლობით და სიყვარულით. ღმერთი მოქმედებს გულში, რომელიც მას გულწრფელად იღებს.', true),
  ('ka', null, null, 'sunday', 'sunday_012', 'მშვიდობა და მადლობა', 'დღეს არის კვირა. ისიამოვნე მიღებული საჩუქრებით და მადლობა ღმერთს მისი заботისთვის.', true),
  ('ka', null, null, 'sunday', 'sunday_013', 'დრო სულისთვის', 'დღეს არის კვირა. მიეცი მეტი დრო ლოცვას და სიმშვიდეს. სულს სჭირდება ღმერთთან სიახლოვე.', true),
  ('ka', null, null, 'sunday', 'sunday_014', 'ლოცვის სიხარული', 'დღეს არის კვირა. სადაც არ უნდა იყო, შეინახე გულში ლოცვის და მშვიდობის სული. ღმერთი აერთიანებს მორწმუნეების გულებს.', true),
  ('ka', null, null, 'sunday', 'sunday_015', 'კვირის კურთხევა', 'დღეს არის კვირა. იცხოვრე ეს დღე მშვიდობით, ლოცვით და სიყვარულით. ყოველი წამი, რომელიც ღმერთთან ახლოს გატარებული, აძლიერებს სულს.', true),
  ('ka', null, null, 'sunday', 'sunday_016', 'ლოცვის სიხარული', 'დღეს არის კვირა. დაიწყე ეს დღე ლოცვით და შეინახე შენი გული ღია ღმერთისკენ. ის აძლევს მშვიდობას მორწმუნე სულს.', true),
  ('ka', null, null, 'sunday', 'sunday_017', 'მშვიდობა სულისთვის', 'დღეს არის კვირა. დაანებე თავი Sorgen-ებს და ეძებე სიმშვიდე ღმერთთან სიახლოვეში. ლოცვა აძლიერებს გულს.', true),
  ('ka', null, null, 'sunday', 'sunday_018', 'წმინდა ლიტურგია', 'დღეს არის კვირა. თუ შეგიძლია, მონაწილეობა მიიღე წმინდა ლიტურგიაში და შეინახე გულში ღმერთთან შეხვედრის სიხარული.', true),
  ('ka', null, null, 'sunday', 'sunday_019', 'სიყვარული ოჯახში', 'დღეს არის კვირა. იყავი მშვიდობის, მოთმინების და კეთილობის წყარო ოჯახში. სიყვარული ძლიერდება მცირე და გულწრფელი საქმეებით.', true),
  ('ka', null, null, 'sunday', 'sunday_020', 'მადლობა და მშვიდობა', 'დღეს არის კვირა. მადლობა ღმერთს ყველა მიღებული სიკეთისთვის და შეინახე მადლიერება გულში.', true),
  ('ka', null, null, 'sunday', 'sunday_021', 'მშვენიერი სიტყვები', 'დღეს არის კვირა. აირჩიე სიტყვები, რომლებიც მოიტანენ წახალისებას და მშვიდობას. გულიდან ნათქვამი კეთილობა მოაქვს სიხარულს.', true),
  ('ka', null, null, 'sunday', 'sunday_022', 'დრო ღმერთთან', 'დღეს არის კვირა. მიეცი ამ დღეს რამდენიმე წუთი სიმშვიდისა და ლოცვისთვის. სულს სჭირდება ღმერთთან სიახლოვე.', true),
  ('ka', null, null, 'sunday', 'sunday_023', 'მშვიდობა და ბოდიშ', 'დღეს არის კვირა. გულით ბოდიშით და ეძებე შერიგება. მშვიდი გული უფრო ადვილად იღებს ღმერთის მშვიდობას.', true),
  ('ka', null, null, 'sunday', 'sunday_024', 'სარწმუნოების სიხარული', 'დღეს არის კვირა. იცხოვრე ეს დღე იმედით და ნდობით. ღმერთი აძლიერებს სულს, რომელიც მას ეძებს.', true),
  ('ka', null, null, 'sunday', 'sunday_025', 'ბედნიერი დღე', 'დღეს არის კვირა. მიიღე ეს დღე თავმდაბლობით და სიყვარულით. ყოველი წამი, რომელიც ღმერთთან ახლოს გატარებული, მოაქვს ნაყოფი.', true),
  ('ka', null, null, 'sunday', 'sunday_026', 'მადლიერი გული', 'დღეს არის კვირა. მადლიერება ხსნის სულს სიხარულისკენ და მშვიდობისკენ. მადლობა ღმერთს ყველაფრისთვის.', true),
  ('ka', null, null, 'sunday', 'sunday_027', 'დასვენება უფალში', 'დღეს არის კვირა. მოიძიე დრო ლოცვისა და სიმშვიდისთვის. ღმერთი აძლევს დასვენებას იმ გულს, რომელიც მას ეძებს.', true),
