  ('ka', null, null, 'sunday', 'sunday_029', 'სიხარული ერთობაში', 'დღეს არის კვირა. გაატარეთ ეს დღე სიყვარულით, მშვიდობით და გაგებით ახლობლებთან. კეთილობა აერთიანებს გულებს.', true),
  ('ka', null, null, 'sunday', 'sunday_030', 'ღმერთთან ახლოს', 'დღეს არის კვირა. დაასრულე ეს დღე ლოცვით და მადლიერებით. ღმერთი რჩება იმედისა და სულის მშვიდობის წყაროს.', true),
  ('mk', null, null, 'black_cross', 'black_cross_001', 'Молитва со смирение', 'Денес е празник со црна крст: {feast_title}. Подигни денес една молитва со смирено срце. Бог ги прима оние кои Го бараат со вера.', true),
  ('mk', null, null, 'black_cross', 'black_cross_002', 'Запомни ја вечноста', 'Денес е празник со црна крст: {feast_title}. Мислата за вечниот живот нè поттикнува да живееме со повеќе љубов, трпение и вера.', true),
  ('mk', null, null, 'black_cross', 'black_cross_003', 'Честитување преку молитва', 'Денес е празник со црна крст: {feast_title}. Почести го овој ден со молитва и добрина. Чистото срце е најубавото сведоштво.', true),
