  ('mk', null, null, 'black_cross', 'black_cross_082', 'Биди благодарен', 'Денес е празник со црн крст: {feast_title}. Благодари му на Бога за секој дар што го добиваш. Благодарноста носи мир и доверба.', true),
  ('mk', null, null, 'black_cross', 'black_cross_083', 'Патот на добрината', 'Денес е празник со црн крст: {feast_title}. Избери го доброто во секое средба и во секоја одлука. Љубовта се гледа преку дела.', true),
