  ('mk', null, null, 'daily', 'daily_051', 'Мирот се чува', 'Не дозволувај немирот да ти го опфати срцето. Молитвата и трпението носат мир.', true),
  ('mk', null, null, 'daily', 'daily_052', 'Љубов преку дела', 'Вистинската љубов се гледа во грижата, трпението и добрината кон ближниот.', true),
  ('mk', null, null, 'daily', 'daily_053', 'Еден корисен ден', 'Направи сè што имаш за да исполниш со чисто срце и со доверба во помошта на Бога.', true),
  ('mk', null, null, 'daily', 'daily_054', 'Гледај напред', 'Не останувај заробен во грешките на минатото. Со покајание и надеж можеш да продолжиш напред.', true),
  ('mk', null, null, 'daily', 'daily_055', 'Нежноста носи мир', 'Едно нежно срце шири тишина во семејството и меѓу оние околу тебе.', true),
  ('mk', null, null, 'daily', 'daily_056', 'Чувај ја верата', 'Верата се зајакнува преку молитва, трпение и доверба во грижата на Бога.', true),
  ('mk', null, null, 'daily', 'daily_057', 'Направи место за мирот', 'Застани за неколку моменти и остави молитвата да ти донесе мир на душата.', true),
  ('mk', null, null, 'daily', 'daily_058', 'Радоста на доброто', 'Радувај се секогаш кога можеш да направиш добро. Љубовта покажана кон ближниот не останува без плод.', true),
  ('mk', null, null, 'daily', 'daily_059', 'Остани блиску до Бога', 'Во секоја околност, сврти го срцето кон Бога. Тој е поддршката на оние кои Го бараат.', true),
  ('mk', null, null, 'daily', 'daily_060', 'Мир и светлина', 'Нека овој ден биде живеен со мир, вера и искрена желба да направиш добро.', true),
  ('mk', null, null, 'daily', 'daily_061', 'Доверба во секој чекор', 'Продолжи напред со вера и остави ги грижите во рацете на Бога. Тој ја зајакнува душата која Го бара.', true),
  ('mk', null, null, 'daily', 'daily_062', 'Остани во мир', 'Не дозволувај немирот да ти го владее срцето. Молитвата носи мир и надеж.', true),
  ('mk', null, null, 'daily', 'daily_063', 'Прави добро со радост', 'Секоја добра работа направена од љубов носи светлина во твојот живот и во животот на оние околу тебе.', true),
  ('mk', null, null, 'daily', 'daily_064', 'Момент на размислување', 'Застани за неколку моменти и зборувај со Бога. Тој слуша молитвата изговорена со искреност.', true),
  ('mk', null, null, 'daily', 'daily_065', 'Силата на трпението', 'Трпението го чува мирот на срцето и ти помага мудро да поминеш низ пробите.', true),
