  ('mk', null, null, 'daily', 'daily_069', 'Мирот на Бога', 'Остави мирот на Бога да ти ги води мислите и да ти ја зајакне душата.', true),
  ('mk', null, null, 'daily', 'daily_070', 'Живеј со нежност', 'Нежноста носи мир во семејството и меѓу луѓето. Избери секогаш добар збор.', true),
