  ('mk', null, null, 'daily', 'daily_085', 'Дневна благодарност', 'Благодари на Бога за секое добро примено. Едно благодарно срце останува полно со надеж.', true),
  ('mk', null, null, 'daily', 'daily_086', 'Биди поддршка', 'Еден добар збор или едноставен гест можат да донесат утеха на ближниот. Прави добро со љубов.', true),
