  ('ru', null, null, 'daily', 'daily_030', 'Мир и благодарность', 'Заканчивай каждый день с благодарностью к Богу. Благодарность приносит покой и укрепляет душу.', true),
  ('ru', null, null, 'daily', 'daily_031', 'Оставайся в молитве', 'Даже короткая молитва, произнесенная с искренностью, приносит покой и укрепление душе.', true),
