  ('uk', null, null, 'daily', 'daily_036', 'Зберігай доброту', 'Доброта, проявлена до ближнього, є свідченням віри, що живеться щиро.', true),
  ('uk', null, null, 'daily', 'daily_037', 'Спокійна душа', 'Шукай спокій, що приходить з близькості до Бога. Він дає силу в будь-якому випробуванні.', true),
  ('uk', null, null, 'daily', 'daily_038', 'Терпіння приносить плоди', 'Не розчаровуйся, якщо відповіді затримуються. Терпіння зміцнює душу і зберігає мир.', true),
  ('uk', null, null, 'daily', 'daily_039', 'Дивись з надією', 'Кожен день приносить нову можливість робити добро і наближатися до Бога.', true),
  ('uk', null, null, 'daily', 'daily_040', 'Мир Христовий', 'Прийми з смиренним серцем мир, який Христос дає тим, хто шукає Його з вірою.', true),
  ('uk', null, null, 'daily', 'daily_041', 'Пробач з любов''ю', 'Прощення звільняє серце від тягаря образи і відкриває шлях до миру.', true),
  ('uk', null, null, 'daily', 'daily_042', 'Корисні слова', 'Обирай слова, які приносять підтримку і доброту. Ніжне слово зближує серця.', true),
  ('uk', null, null, 'daily', 'daily_043', 'Надія на кожен день', 'Як би важким не здавався шлях, Бог залишається підтримкою тих, хто Його шукає.', true),
  ('uk', null, null, 'daily', 'daily_044', 'Живи зі смиренням', 'Смирення приносить спокій душі і допомагає приймати волю Бога з упевненістю.', true),
  ('uk', null, null, 'daily', 'daily_045', 'Мир у душі', 'Довір цю добу Богові і йди вперед з вірою, терпінням і вдячністю.', true),
  ('uk', null, null, 'daily', 'daily_046', 'Радій кожному дню', 'Приймай кожен день як дар Божий. Живи його з вірою, добротою і миром.', true),
  ('uk', null, null, 'daily', 'daily_047', 'Вдячне серце', 'Подяка Богові приносить спокій і зміцнює душу в усіх обставинах.', true),
  ('uk', null, null, 'daily', 'daily_048', 'Залишайся стійким', 'Не відмовляйся від молитви, навіть якщо шлях здається важким. Бог близький до тих, хто Його шукає.', true),
  ('uk', null, null, 'daily', 'daily_049', 'Почни з добра', 'Вибери зробити перший крок до добра ще з самого початку дня. Добрі вчинки приносять мир у серце.', true),
  ('uk', null, null, 'daily', 'daily_050', 'Шукай мудрість', 'Помолися до Бога, щоб Він просвітив твої думки і направив твої кроки на добрий шлях.', true),
