  ('uk', null, null, 'daily', 'daily_052', 'Любов через вчинки', 'Справжня любов проявляється в турботі, терпінні і доброті до ближнього.', true),
  ('uk', null, null, 'daily', 'daily_053', 'Корисний день', 'Роби все, що маєш виконати, з чистим серцем і з упевненістю в допомозі Бога.', true),
  ('uk', null, null, 'daily', 'daily_054', 'Дивись вперед', 'Не залишайся прив''язаним до помилок минулого. З покаянням і надією ти можеш йти вперед.', true),
  ('uk', null, null, 'daily', 'daily_055', 'Ніжність приносить мир', 'Ніжне серце розповсюджує спокій у родині та серед оточуючих.', true),
  ('uk', null, null, 'daily', 'daily_056', 'Зберігай віру', 'Віра зміцнюється через молитву, терпіння і довіру до турботи Бога.', true),
